type Listener<T> = (...args: T[]) => unknown;

interface EventEmitter {
  on: (event: string, listener: Listener<unknown>) => void;
  once: (event: string, listener: Listener<unknown>) => void;
  off: (event: string, listener: Listener<unknown>) => void;
  emit: <T>(event: string, ...args: T[]) => unknown[];
}

function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener<unknown>[][]>();

  return {
    on(event: string, listener: Listener<unknown>): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      const eventListeners = listeners.get(event)!;
      // Create a new array to avoid modifying the existing one during iteration
      eventListeners.push([listener]);
    },

    once(event: string, listener: Listener<unknown>): void {
      const wrapper: Listener<unknown> = (...args) => {
        this.off(event, wrapper);
        return listener(...args);
      };
      this.on(event, wrapper);
    },

    off(event: string, listener: Listener<unknown>): void {
      if (!listeners.has(event)) {
        return;
      }
      const eventListeners = listeners.get(event)!;
      for (let i = 0; i < eventListeners.length; i++) {
        if (eventListeners[i][0] === listener) {
          eventListeners.splice(i, 1);
          break;
        }
      }
    },

    emit<T>(event: string, ...args: T[]): unknown[] {
      if (!listeners.has(event)) {
        return [];
      }
      // Clone the current listeners to avoid issues if listeners are added/removed during emission
      const currentListeners = listeners.get(event)!;
      const results: unknown[] = [];

      // Iterate through all registered listener groups
      for (const group of currentListeners) {
        for (const listener of group) {
          const result = listener(...args);
          results.push(result);
        }
      }

      return results;
    }
  };
}
