```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const listeners: Record<string, { fn: Listener; once: boolean }[]> = {}

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = []
      }
      listeners[event].push({ fn: listener, once: false })
      return listeners[event].length
    },

    once(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = []
      }
      listeners[event].push({ fn: listener, once: true })
      return listeners[event].length
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners[event]) {
        return false
      }
      const index = listeners[event].findIndex(item => item.fn === listener)
      if (index === -1) {
        return false
      }
      listeners[event].splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners[event]) {
        return []
      }

      const results: unknown[] = []
      const eventsToCall = [...listeners[event]]
      listeners[event] = []

      for (const { fn, once } of eventsToCall) {
        const result = fn(payload)
        results.push(result)
        if (!once) {
          listeners[event].push({ fn, once: false })
        }
      }

      return results
    },

    listenerCount(event: string): number {
      return listeners[event] ? listeners[event].length : 0
    }
  }
}

export { createEventEmitter }
