type WindowState = {
  count: number;
  windowStartMs: number | null;
};

type RateLimiter = {
  allow(key: string, nowMs: number): boolean;
  reset(key: string): void;
};

export const createRateLimiter = (): RateLimiter => {
  const windows: Map<string, WindowState> = new Map();
  const MAX_REQUESTS = 3;
  const WINDOW_SIZE_MS = 1000;

  return {
    allow(key: string, nowMs: number): boolean {
      let state = windows.get(key);

      if (!state) {
        state = { count: 0, windowStartMs: nowMs };
        windows.set(key, state);
      }

      if (state.windowStartMs === null) {
        state.windowStartMs = nowMs;
        state.count = 0;
      } else if (nowMs - state.windowStartMs >= WINDOW_SIZE_MS) {
        state.windowStartMs = nowMs;
        state.count = 0;
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }

      return false;
    },

    reset(key: string): void {
      windows.delete(key);
    }
  };
};
