export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs: number = 1000
  ): void {
    const expiresAt = nowMs + ttlMs;
    cache.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (!entry) return undefined;
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return false;
    }
    return true;
  }

  function deleteKey(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of cache.entries()) {
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
      } else {
        count++;
      }
    }
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}
