export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    if (ttlMs === 0) {
      cache.delete(key);
    } else {
      cache.set(key, { value, expiresAt: nowMs + ttlMs });
    }
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    if (!entry) {
      return undefined;
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return undefined;
    }
    return entry.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    if (!entry) {
      return false;
    }
    if (nowMs >= entry.expiresAt) {
      cache.delete(key);
      return false;
    }
    return true;
  }

  function deleteEntry(key: string): boolean {
    return cache.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [key, entry] of cache.entries()) {
      if (nowMs < entry.expiresAt) {
        count++;
      } else {
        cache.delete(key);
      }
    }
    return count;
  }

  function clear(): void {
    cache.clear();
  }

  return { set, get, has, delete: deleteEntry, size, clear };
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
