export function createEventEmitter(): {
    on(name: string, listener: (...args: any[]) => void): this;
    once(name: string, listener: (...args: any[]) => void): this;
    off(name: string, listener: (...args: any[]) => void): this;
    emit(name: string, data: unknown): unknown[];
} {
    const listeners: Record<
        string,
        Array<{ fn: (...args: any[]) => void; once: boolean }>
    > = {};

    return {
        on(name: string, listener: (...args: any[]) => void) {
            if (!listeners[name]) listeners[name] = [];
            listeners[name].push({ fn: listener, once: false });
            return this;
        },
        once(name: string, listener: (...args: any[]) => void) {
            if (!listeners[name]) listeners[name] = [];
            listeners[name].push({ fn: listener, once: true });
            return this;
        },
        off(name: string, listener: (...args: any[]) => void) {
            const list = listeners[name];
            if (list) {
                const idx = list.findIndex(l => l.fn === listener);
                if (idx !== -1) list.splice(idx, 1);
            }
            return this;
        },
        emit(name: string, data: unknown) {
            const list = listeners[name];
            if (!list) return [];
            const results: unknown[] = [];
            // Iterate backwards to safely splice 'once' listeners
            for (let i = list.length - 1; i >= 0; i--) {
                const { fn, once } = list[i];
                results.push(fn(data));
                if (once) list.splice(i, 1);
            }
            return results;
        }
    };
}
