type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  type ListenerEntry = { fn: Listener; type: 'normal' | 'once' };
  const store: Record<string, ListenerEntry[]> = {};

  const getEntries = (event: string) => {
    if (!store[event]) {
      store[event] = [];
    }
    return store[event];
  };

  return {
    on(event: string, listener: Listener): number {
      getEntries(event).push({ fn: listener, type: 'normal' });
      return getEntries(event).length;
    },

    once(event: string, listener: Listener): number {
      getEntries(event).push({ fn: listener, type: 'once' });
      return getEntries(event).length;
    },

    off(event: string, listener: Listener): boolean {
      if (!store[event]) return false;
      const idx = store[event].findIndex((item) => item.fn === listener);
      if (idx === -1) return false;
      store[event].splice(idx, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!store[event]) return [];
      const entries = store[event];
      const copy = [...entries];
      const results: unknown[] = [];

      for (const entry of copy) {
        results.push(entry.fn(payload));
        if (entry.type === 'once') {
          const idx = entries.indexOf(entry);
          if (idx !== -1) {
            entries.splice(idx, 1);
          }
        }
      }

      return results;
    },

    listenerCount(event: string): number {
      return store[event]?.length ?? 0;
    },
  };
}
