export const createRateLimiter = (nowMs: () => number): RateLimiter => {
    const state = new Map<string, { count: number; resetAt: number }>();
    const WINDOW = 1000;
    const LIMIT = 3;

    const check = (key: string): boolean => {
        const now = nowMs();
        const entry = state.get(key);

        if (!entry || now > entry.resetAt) {
            state.set(key, { count: 1, resetAt: now + WINDOW });
            return true;
        }

        if (entry.count < LIMIT) {
            entry.count++;
            state.set(key, entry);
            return true;
        }

        return false;
    };

    const reset = (key: string): void => {
        state.delete(key);
    };

    return Object.assign(check, { reset });
};
