```typescript
const LIMIT = 3;
const WINDOW_MS = 1000;

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

interface WindowState {
  windowStart: number;
  count: number;
}

export function createRateLimiter(): RateLimiter {
  const store = new Map<string, WindowState>();

  const ensureWindow = (key: string, nowMs: number): WindowState => {
    let state = store.get(key);
    if (!state || nowMs - state.windowStart >= WINDOW_MS) {
      state = { windowStart: nowMs, count: 0 };
      store.set(key, state);
    }
    return state;
  };

  return {
    allow(key: string, nowMs: number): boolean {
      const state = ensureWindow(key, nowMs);
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key: string, nowMs: number): number {
      const state = ensureWindow(key, nowMs);
      const remaining = LIMIT - state.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key: string): void {
      store.delete(key);
    }
  };
}
