export function createTtlCache() {
  const DEFAULT_TTL = 1000;
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL): void {
      cache.set(key, {
        value,
        expiresAt: nowMs + ttlMs,
      });
    },
    get(key: string, nowMs: number): unknown {
      const item = cache.get(key);
      if (!item) return undefined;
      if (nowMs >= item.expiresAt) {
        cache.delete(key);
        return undefined;
      }
      return item.value;
    },
    has(key: string, nowMs: number): boolean {
      const item = cache.get(key);
      if (!item) return false;
      if (nowMs >= item.expiresAt) {
        cache.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return cache.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      const keysToDelete: string[] = [];
      for (const [key, item] of cache) {
        if (nowMs < item.expiresAt) {
          count++;
        } else {
          keysToDelete.push(key);
        }
      }
      keysToDelete.forEach(key => cache.delete(key));
      return count;
    },
    clear(): void {
      cache.clear();
    },
  };
}
