            const firedListeners = new Array();
            for (const [key] of listenersMap) {
                if (key.eventName === eventName) {
                    firedListeners.push(key);
                }
            }
            return firedListeners;
        },
        on(eventName: string, callback: (...args: any[]) => void): void {
            // Register new listener for given name.
            listenersMap.set(eventName, new { ... });
        },
        off(eventName: string): void {
