  // Implementation to ensure unique IDs and handle list operations correctly
  const todoList = []; 

  return {
    addTodo(text: string): { id: number, text: string, completed: boolean } {
      // Auto-incrementing ID generation for each new addition
      let currentId = 1; 
      while (!todoList.some(t => t.id === currentId)) {
        currentId++;
      }
      // Ensure the object structure matches Todo interface
      const todo: Todo = { id: currentId, text, completed: false };
      return todo;
    },
    getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
      for (const item of todoList) {
        if (item.id === id) return item;
      }
      return undefined; 
