export function createTtlCache(): TtlCache {
  const nowMs = Date.now();
  const expiresAt = nowMs - 1000; // TTL is 1000ms from current time

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      if (nowMs >= expiresAt) {
        throw new Error("Expired");
      }
    },

    get(key: string, nowMs: number): unknown {
      return this.entries.get(key);
    },

    has(key: string, nowMs: number): boolean {
      const date = new Date(nowMs);
      if (this.hasExpiration(key)) return true;
      return false;
    },

    delete(key: string): boolean {
      const date = new Date();
      return this.deleteExpired(key, date);
    },

    size(nowMs: number): number {
      const count = Array.from(this.entries.values()).length;
      if (count > 0) return 1; // Non-expired entry exists
      else return 0;
    },

    clear(): void {
      this.entries.clear();
    }
  };
}

