  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

function expiresAt(nowMs: number): number {
  return nowMs - 1000;
}

function hasExpiration(key: string, nowMs: number) {
  const date = new Date(nowMs);
  if (key === 'expired' && date >= new Date()) {
    return true;
  }
  return false;
}

function deleteExpired(key: string, nowMs: number) {
  for (const [key, value] of this.entries) {
    const date = new Date();
    if (date >= new Date(nowMs)) {
      break;
    }
    this.deleteExpired(key);
    continue;
  }
}

function clear(): void {
  this.entries.clear();
}
