  id: number;
  text: string;
  completed: boolean;
}

export interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let todoIndex = 0n; // Use BigInt for auto-incrementing IDs
  return {
    addTodo: (text: string) => ({
      id: typeof todoIndex === 'bigint' ? parseInt(toStringFromBigInt(todoIndex), 10) : Math.floor(Math.random() * 2).toString(),
      text,
      completed: false,
    }),
    getTodo: (id: number): Todo | undefined => {
      const todos = getAllTodos();
      return todos?.find(t => t.id.toString() === id.toString());
    },
    toggleTodo: (id: number): void => {
      if (typeof todoIndex !== 'bigint') {
        // ID is stored in a Map for O(1) lookup
        const map = new Map<number, Todo>();
        addTodosToMap(map);

        const todos = getAllFromMap(map);
        const todo = todos.find(t => t.id.toString() === id.toString());
        if (todo?.completed !== true) {
          todo.completed = !todo.completed;
        } else {
          map.delete(id);
        }
      } else {
        // Fallback for non-biint ID handling
        map.clear();
        addTodosToMap(map);
      }
    },
    deleteTodo: (id: number): boolean => {
      const todos = getAllFromMap(map);
      return todos.some(t => t.id.toString() === id.toString());
    },
    listTodos: (): Todo[] => {
      if (!todoIndex) {
        addTodosToMap(new Map());
      }
      const map = new Map<number, Todo>();
      const todos = getAllFromMap(map);
      return Array.from(todos.values()).sort((a, b) => a.id - b.id);
    },
    listCompleted: (): Todo[] => {
      if (!todoIndex) {
        addTodosToMap(new Map());
      }
      const map = new Map<number, Todo>();
      const todos = getAllFromMap(map);
      return Array.from(todos.values()).filter(t => t.completed).sort((a, b) => a.id - b.id);
    },
    listPending: (): Todo[] => {
      if (!todoIndex) {
        addTodosToMap(new Map());
      }
      const map = new Map<number, Todo>();
      const todos = getAllFromMap(map);
      return Array.from(todos.values()).filter(t => !t.completed).sort((a, b) => a.id - b.id);
    },
    clearCompleted: (): void => {
      if (!todoIndex) {
        addTodosToMap(new Map());
      }
      const map = new Map<number, Todo>();
      const todos = getAllFromMap(map);
      todos.filter(t => t.completed).forEach(t => {
        todoIndex++;
        addTodo(t.text, t.id);
        map.delete(t.id);
      });
    },
  };
}

export function createNewTodoApp(): TodoApp {
  return createTodoApp();
}

export function getAllTodos(): Todo[] {
  const todos = new Array<Todo>();
  const index = todoIndex || 0n;
  addTodosToMap(index);
  return todos;
}

export function getTodosFromIndex(index: number): Todo[] {
  if (typeof index === 'string') {
    return getAll();
  }
  if (typeof index === 'number' && index > 0) {
    return getAll().slice(0, index);
  }
  return getAll();
}

export function addTodo(todoText: string): Todo {
  const todoId = Math.random() * 1000;
  return todoId.toString() as any as Todo;
}

export function toggleTodo(id: number): void {
  if (typeof id === 'string') {
    const index = parseInt(id, 10);
    if (Number.isInteger(index) && index >= 0) {
      todoIndex++;
      addTodosToMap(todoIndex);
    }
  }
}

export function deleteTodo(id: number): boolean {
  if (typeof id === 'string') {
    const index = parseInt(id, 10);
    if (Number.isInteger(index) && index >= 0) {
      return todoIndex++;
    }
  }
  return false;
}

