export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const currentTtl = ttlMs ?? 1000;
      const expirationTime = nowMs + currentTtl;
      cache.set(key, { value, expiresAt: expirationTime });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) return false;
      return true;
    },

    delete(key: string): boolean {
      const entry = cache.get(key);
      if (!entry) return false;
      cache.delete(key);
      return true;
    },

    size(nowMs: number): number {
      return [...cache.values()].length;
    },

    clear(): void {
      cache.clear();
    }
  };
}
