export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export class CacheImpl implements TtlCache {
  private keys: Map<string, { value: unknown; expiresAt: number }> = new Map();

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    if (!ttlMs) {
      ttlMs = 1000;
    }
    const expiresAt = nowMs + (ttlMs || 1000);
    this.keys.set(key, { value, expiresAt });
  }

  get(key: string, nowMs: number): unknown {
    return this.keys.get(key) ? this.keys.get(key).value : undefined;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.keys.get(key);
    if (!entry) return false;
    return entry.expiresAt > nowMs;
  }

  delete(key: string): boolean {
    if (this.keys.has(key)) {
      this.keys.delete(key);
      return true;
    }
    return false;
  }

  size(nowMs: number): number {
    const count = this.keys.size;
    const mapEntries: Array<[string, { value: unknown; expiresAt: number }>]> = [];
    for (const [key, entry] of this.keys.entries()) {
      if (entry.expiresAt > nowMs) {
        mapEntries.push(entry);
      }
    }
    return mapEntries.length;
  }

  clear(): void {
    this.keys.clear();
  }
}

export function createTtlCache(): TtlCache {
  return new CacheImpl();
}
