interface Calculator {
  add(a: number): Calculator;
  subtract(a: number): Calculator;
  multiply(a: number): Calculator;
  divide(a: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryAdd(): Calculator;
  memoryRecall(): number;
}

function createCalculator(): Calculator {
  let currentValue: number = 0;
  let memoryValue: number = 0;

  return {
    add(a: number): Calculator {
      currentValue += a;
      return this;
    },
    subtract(a: number): Calculator {
      currentValue -= a;
      return this;
    },
    multiply(a: number): Calculator {
      currentValue *= a;
      return this;
    },
    divide(a: number): Calculator {
      if (a === 0) {
        throw new Error("Cannot divide by zero");
      }
      currentValue /= a;
      return this;
    },
    clear(): Calculator {
      currentValue = 0;
      return this;
    },
    result(): number {
      return currentValue;
    },
    memoryStore(): Calculator {
      memoryValue = currentValue;
      return this;
    },
    memoryAdd(): Calculator {
      memoryValue += currentValue;
      return this;
    },
    memoryRecall(): number {
      return memoryValue;
    },
  };
}

export { createCalculator };
