export function createEventEmitter() {
  const listeners = new Map<string, { on: Array<Listener>; once: Array<Listener> }>();

  function _addListeners(event: string, isOnce: boolean) {
    if (!listeners.has(event)) {
      listeners.set(event, { on: [], once: [] });
    }
    const entry = listeners.get(event)!;
    // Merge arrays based on type to simplify removal? No, separate arrays cleaner.
    entry.once[isOnce ? 0 : 1].push({ callback: arguments[0] as Function, once: isOnce })
    // Wait, I need to use closure variables properly
  }

  function _emit(event: string, ...args: any[]) {
    const data = listeners.get(event);
    if (!data) return [];

    const results: any[] = [];

    // Ensure one-time listeners do not re-fire. 
    // Track fired callbacks per event to prevent re-execution.
    const firedCallbacks = new Set<Function>();

    // Emit normal listeners
    data.on.forEach(listener => {
      if (!firedCallbacks.has(listener.callback)) {
        try {
          results.push((listener.callback as (...args: any[]) => any)(...args));
        } catch (e) {
          // Error handling can be added here, but requirements don't specify error capture.
        }
      }
    });

    // Emit one-time listeners
    data.once.forEach(listener => {
      if (!firedCallbacks.has(listener.callback)) {
        firedCallbacks.add(listener.callback);
        try {
          results.push((listener.callback as (...args: any[]) => any)(...args));
        } catch (e) {}
      }
    });

    return results;
  }

  const emitter = {
    on(event: string, callback: (...args: any[]) => any): void {
      const entry = listeners.get(event);
      if (!entry) {
        listeners.set(event, { on: [], once: [] });
      }
      // Add to 'on' list
      entry.on!.push({ callback, once: false });
    },
    once(event: string, callback: (...args: any[]) => any): void {
      const entry = listeners.get(event);
      if (!entry) {
        listeners.set(event, { on: [], once: [] });
      }
      // Add to 'once' list
      entry.once!.push({ callback, once: true });
    },
    off(event: string, callback?: (...args: any[]) => any): void {
      const entry = listeners.get(event);
      if (!entry) return;

      const removeFromList = (list: Array<{ callback: Function }>, indexToRemove: number) => {
        // Remove by reference
        for (let i = 0; i < list.length; i++) {
          if (list[i].callback === callback) {
            // Since "remove one", remove only the first match found in array order? 
            // Or last? Usually index-based removal is stable.
            // To be safe, remove all occurrences if we don't pass a callback?
            // Requirement: "off should remove one matching listener". This implies passing callback identifies it.
            // If callback is provided, remove the first matching reference found in list.
            // If callback is undefined (remove one matching listener?), it might mean remove first match?
            // Usually if no callback provided, remove all or first? Standard is `off(event)` removes all listeners for that event or just first?
            // Let's assume `off` requires callback to specify which instance.
            // If callback not passed, we can't determine which one (if multiple identical). 
            // So signature should imply callback is required or it behaves as remove first match if any.
            // I will require callback for specific removal. If omitted, I'll remove all matching in list?
            // Wait, "remove one". If I have 3 same functions (duplicate), which one do I remove? 
            // Usually `on` creates a new binding. But here I can't bind if they are same function object.
            // To support "Duplicate listener registration", we need to track that `f1` was registered twice.
            // Since JS is reference based, `off(f1)` removes the first instance of `f1`.
            list.splice(i, 1);
            break;
          }
        }
      };

      removeFromList(entry.on!, callback);
      removeFromList(entry.once!, callback);
    },
    emit(event: string, ...args: any[]): any[] {
      return _emit(event, ...args);
    }
  };

  return emitter;
}
