export function createRateLimiter(): {
    check: (key: string, nowMs: number) => boolean;
    reset: (key: string) => void;
} {
    const state = new Map<string, { count: number; lastWindowTime: number }>();

    return {
        check(key: string, nowMs: number): boolean {
            const policy = { limit: 3, window: 1000 };

            let record = state.get(key);
            if (!record) {
                record = { count: 0, lastWindowTime: 0 };
                state.set(key, record);
            }

            // Check if the new timestamp has ended the current window
            if (nowMs >= record.lastWindowTime + policy.window) {
                record.count = 0;
                record.lastWindowTime = nowMs;
            }

            // Allow request if under limit
            if (record.count < policy.limit) {
                record.count++;
                return true;
            } else {
                return false;
            }
        },
        reset(key: string): void {
            const record = state.get(key);
            if (record) {
                record.count = 0;
            }
        }
    };
}
