export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

class RateLimiterImpl implements RateLimiter {
  private limit = 3;
  private windowMs = 1000;
  private state: Map<string, { count: number; startTime: number }> = new Map();

  allow(key: string, nowMs: number): boolean {
    const entry = this.state.get(key);

    if (!entry) {
      // New key starts a fresh window
      this.state.set(key, { count: 0, startTime: nowMs });
      return true;
    }

    // Check boundary reset rule
    if (nowMs - entry.startTime >= this.windowMs) {
      // Start fresh window
      entry.count = 0;
      entry.startTime = nowMs;
    }

    if (entry.count < this.limit) {
      entry.count++;
      this.state.set(key, entry);
      return true;
    } else {
      return false;
    }
  }

  remaining(key: string, nowMs: number): number {
    const entry = this.state.get(key);

    if (!entry) {
      // New key -> full quota available in current window context
      return this.limit;
    }

    // Apply boundary reset rule logic here too for consistency with 'nowMs'
    if (nowMs - entry.startTime >= this.windowMs) {
      return this.limit;
    }

    return Math.max(0, this.limit - entry.count);
  }

  reset(key: string): void {
    this.state.delete(key);
  }
}

export function createRateLimiter(): RateLimiter {
  return new RateLimiterImpl() as any;
}
