export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const internalMap = new Map<string, { value: unknown; expiresAt: number }>();

  const set = (key: string, value: unknown, nowMs: number, ttlMs?: number): void => {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    internalMap.set(key, { value, expiresAt });
  };

  const get = (key: string, nowMs: number): unknown => {
    const entry = internalMap.get(key);
    if (!entry || entry.expiresAt <= nowMs) return undefined;
    return entry.value;
  };

  const has = (key: string, nowMs: number): boolean => {
    const entry = internalMap.get(key);
    return !!(entry && entry.expiresAt > nowMs);
  };

  const delete = (key: string): boolean => {
    return internalMap.delete(key);
  };

  const size = (nowMs: number): number => {
    let count = 0;
    for (const entry of internalMap.values()) {
      if (entry.expiresAt > nowMs) {
        count++;
      }
    }
    return count;
  };

  const clear = (): void => {
    internalMap.clear();
  };

  return { set, get, has, delete, size, clear };
}
