const DEFAULT_TTL_MS = 1000;

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const storage = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs ?? DEFAULT_TTL_MS);
      storage.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = storage.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = storage.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return storage.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const [key, entry] of storage.entries()) {
        if (!entry || nowMs >= entry.expiresAt) {
          continue;
        }
        count++;
      }
      return count;
    },

    clear(): void {
      storage.clear();
    }
  };
}
