type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  return {
    on(event: string, listener: Listener): number {
      const currentListeners = listeners.get(event);
      if (!currentListeners) {
        listeners.set(event, [{ fn: listener, once: false }]);
        return 1;
      }
      currentListeners.push({ fn: listener, once: false });
      return currentListeners.length;
    },

    once(event: string, listener: Listener): number {
      const currentListeners = listeners.get(event);
      if (!currentListeners) {
        listeners.set(event, [{ fn: listener, once: true }]);
        return 1;
      }
      currentListeners.push({ fn: listener, once: true });
      return currentListeners.length;
    },

    off(event: string, listener: Listener): boolean {
      const currentListeners = listeners.get(event);
      if (!currentListeners) {
        return false;
      }
      const index = currentListeners.findIndex(l => l.fn === listener);
      if (index !== -1) {
        currentListeners.splice(index, 1);
        return true;
      }
      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      const currentListeners = listeners.get(event);
      if (!currentListeners || currentListeners.length === 0) {
        return [];
      }

      const results: unknown[] = [];
      let i = 0;

      while (i < currentListeners.length) {
        const listenerObj = currentListeners[i];
        // If listener throws, we break to match EventEmitter semantics of propagation
        // without swallowing the error, though strictly return array implies valid calls
        const result = listenerObj.fn(payload); 
        results.push(result);

        if (listenerObj.once) {
          currentListeners.splice(i, 1);
        } else {
          i++;
        }
      }

      return results;
    },

    listenerCount(event: string): number {
      const currentListeners = listeners.get(event);
      return currentListeners ? currentListeners.length : 0;
    },
  };
}
