  addTodo: (text: string) => { id: number; text: string; completed: boolean };
  getTodo: (id: number) => { id: number; text: string, completed: boolean } | undefined;
  toggleTodo: (id: number) => void;
  deleteTodo: (id: number) => boolean;
  listTodos: () => Array<{ id: number; text: string; completed: boolean }>;
  listCompleted: () => Array<{ id: number; text: string; completed: boolean }>;
  listPending: () => Array<{ id: number; text: string; completed: boolean }>;
  clearCompleted: () => void;
} {
  const todos = new Map<number, { id: number; text: string; completed: boolean }>();
  let nextId = 1;

  return {
    addTodo(text: string): { id: number, text: string, completed: boolean } {
      const id = nextId++;
      const todo = { id, text, completed: false };
      todos.set(id, todo);
      return todo;
    },
    getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
      return todos.get(id);
    },
    toggleTodo(id: number): void {
      const existing = todos.get(id);
      if (existing) {
        existing.completed = !existing.completed;
      }
    },
    deleteTodo(id: number): boolean {
      const existed = todos.has(id);
      if (existed) {
        todos.delete(id);
      }
      return existed;
    },
    listTodos(): Array<{ id: number, text: string, completed: boolean }> {
      return Array.from(todos.values());
    },
    listCompleted(): Array<{ id: number, text: string, completed: boolean }> {
      const results = [];
      for (const todo of todos.values()) {
        if (todo.completed) {
          results.push(todo);
        }
      }
      return results;
    },
    listPending(): Array<{ id: number, text: string, completed: boolean }> {
      const results = [];
      for (const todo of todos.values()) {
        if (!todo.completed) {
          results.push(todo);
        }
      }
      return results;
