    clearCompleted(): void {
      const keysToClear: number[] = [];
      for (const [key, value] of todos.entries()) {
        if (value.completed) {
          keysToClear.push(key);
        }
      }
      for (const key of keysToClear) {
        todos.delete(key);
      }
    },
  };
}
