export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const ttl = ttlMs ?? 1000;
      cache.set(key, { value, expiresAt: nowMs + ttl });
    },
    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        cache.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      const existed = cache.has(key);
      if (existed) {
        cache.delete(key);
      }
      return existed;
    },
    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      cache.clear();
    }
  };
