type Calculator = {
  add(val: number): Calculator;
  subtract(val: number): Calculator;
  multiply(val: number): Calculator;
  divide(val: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryAdd(): Calculator;
  memoryClear(): Calculator;
  memoryRecall(): number;
};

export function createCalculator(): Calculator {
  let current = 0;
  let memory = 0;

  const calc: Calculator = {
    add(val) {
      current += val;
      return calc;
    },
    subtract(val) {
      current -= val;
      return calc;
    },
    multiply(val) {
      current *= val;
      return calc;
    },
    divide(val) {
      current /= val;
      return calc;
    },
    clear() {
      current = 0;
      return calc;
    },
    result() {
      return current;
    },
    memoryStore() {
      memory = current;
      return calc;
    },
    memoryAdd() {
      memory += current;
      return calc;
    },
    memoryClear() {
      memory = 0;
      return calc;
    },
    memoryRecall() {
      return memory;
    }
  };

  return calc;
}
