export function createRateLimiter(): {
  check: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
} {
  const WINDOW_SIZE_MS = 1000;
  const MAX_REQUESTS = 3;
  const store = new Map<string, { windowId: number; count: number }>();

  return {
    check(key: string, nowMs: number): boolean {
      const currentWindowId = Math.floor(nowMs / WINDOW_SIZE_MS);
      let state = store.get(key);

      if (!state || state.windowId !== currentWindowId) {
        state = { windowId: currentWindowId, count: 0 };
        store.set(key, state);
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }
      return false;
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}
