export function createEventEmitter() {
  const listeners = new Map<string, Array<{ callback: (...args: any[]) => any; once: boolean }>>();

  function on(event: string, callback: (...args: any[]) => any) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const list = listeners.get(event)!;
    list.push({ callback, once: false });
  }

  function once(event: string, callback: (...args: any[]) => any) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    const list = listeners.get(event)!;
    list.push({ callback, once: true });
  }

  function off(event: string, callback: (...args: any[]) => any) {
    const list = listeners.get(event);
    if (!list) return;
    for (let i = 0; i < list.length; i++) {
      if (list[i].callback === callback) {
        list.splice(i, 1);
        break;
      }
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const list = listeners.get(event);
    if (!list || list.length === 0) return [];

    const results: any[] = [];
    const survivors: Array<{ callback: (...args: any[]) => any; once: boolean }> = [];

    for (const sub of list) {
      try {
        const result = sub.callback(...args);
        results.push(result);
        if (!sub.once) {
          survivors.push(sub);
        }
      } catch {
        if (!sub.once) {
          survivors.push(sub);
        }
      }
    }

    listeners.set(event, survivors);
    return results;
  }

  return { on, once, off, emit };
}
