```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener[]>();

  function on(event: string, listener: Listener): number {
    let list = listeners.get(event);
    if (!list) {
      list = [];
      listeners.set(event, list);
    }
    list.push(listener);
    return list.length;
  }

  function once(event: string, listener: Listener): number {
    const handler: Listener = (payload) => {
      const result = listener(payload);
      off(event, handler);
      return result;
    };
    let list = listeners.get(event);
    if (!list) {
      list = [];
      listeners.set(event, list);
    }
    list.push(handler);
    return list.length;
  }

  function off(event: string, listener: Listener): boolean {
    const list = listeners.get(event);
    if (list) {
      const index = list.indexOf(listener);
      if (index !== -1) {
        list.splice(index, 1);
        return true;
      }
    }
    return false;
  }

  function emit(event: string, payload: unknown): unknown[] {
    const list = listeners.get(event);
    if (!list) return [];
    const snapshot = [...list];
    const results = [] as unknown[];
    for (const l of snapshot) {
      results.push(l(payload));
    }
    return results;
  }

  function listenerCount(event: string): number {
    return listeners.get(event)?.length ?? 0;
  }

  return { on, once, off, emit, listenerCount };
}
