export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const defaultTtl = 1000;
  const entries = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = ttlMs !== undefined ? ttlMs : defaultTtl;
      entries.set(key, {
        value,
        expiresAt: nowMs + ttl,
      });
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry) {
        return undefined;
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry) {
        return false;
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return entries.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      const expiredKeys: string[] = [];

      for (const [key, entry] of entries) {
        if (nowMs < entry.expiresAt) {
          count++;
        } else {
          expiredKeys.push(key);
        }
      }

      for (const key of expiredKeys) {
        entries.delete(key);
      }

      return count;
    },

    clear(): void {
      entries.clear();
    },
  };
}
