```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const events: Map<string, { listener: Listener; once: boolean }[]> = new Map()

  return {
    on(event: string, listener: Listener): number {
      const listeners = events.get(event) || []
      listeners.push({ listener, once: false })
      events.set(event, listeners)
      return listeners.length
    },

    once(event: string, listener: Listener): number {
      const listeners = events.get(event) || []
      listeners.push({ listener, once: true })
      events.set(event, listeners)
      return listeners.length
    },

    off(event: string, listener: Listener): boolean {
      const listeners = events.get(event)
      if (!listeners) {
        return false
      }
      const index = listeners.findIndex(
        (item) => item.listener === listener
      )
      if (index === -1) {
        return false
      }
      listeners.splice(index, 1)
      if (listeners.length === 0) {
        events.delete(event)
      } else {
        events.set(event, listeners)
      }
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const listeners = events.get(event)
      if (!listeners) {
        return []
      }
      const results: unknown[] = []
      const toCall = [...listeners]
      for (let i = 0; i < toCall.length; i++) {
        const { listener, once } = toCall[i]
        const result = listener(payload)
        results.push(result)
        if (once) {
          listeners.splice(i, 1)
          i--
        }
      }
      if (listeners.length === 0) {
        events.delete(event)
      } else {
        events.set(event, listeners)
      }
      return results
    },

    listenerCount(event: string): number {
      const listeners = events.get(event)
      return listeners ? listeners.length : 0
    },
  }
}

export { createEventEmitter }
