interface RateLimiterState {
  count: number;
  windowStart: number;
}

type RateLimiter = {
  isAllowed: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
};

export function createRateLimiter(): RateLimiter {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;
  const state: Map<string, RateLimiterState> = new Map();

  function isAllowed(key: string, nowMs: number): boolean {
    const current = state.get(key);

    if (!current || nowMs >= current.windowStart + WINDOW_MS) {
      // Start fresh window
      state.set(key, {
        count: 1,
        windowStart: nowMs
      });
      return true;
    }

