export interface Event {
    (): void;
}

export type Listener = (...args: any[]) => any;

export interface EventEmitter {
    on(event: string, listener: Listener): EventEmitter;
    once(event: string, listener: Listener): EventEmitter;
    off(event: string, listener: Listener): void;
    emit(event: string, ...args: any[]): any[];
    removeAllListeners(event?: string): void;
}

export function createEventEmitter(): EventEmitter {
    const listeners: Map<string, Listener[]> = new Map();

    function on(event: string, listener: Listener): EventEmitter {
        if (!listeners.has(event)) {
            listeners.set(event, []);
        }
        listeners.get(event)!.push(listener);
        return emitter;
    }

    function once(event: string, listener: Listener): EventEmitter {
        const onceWrapper: Listener = (...args: any[]) => {
            listener(...args);
            const eventListeners = listeners.get(event);
            if (eventListeners) {
                const index = eventListeners.indexOf(onceWrapper);
                if (index !== -1) {
                    eventListeners.splice(index, 1);
                }
            }
        };
        return on(event, onceWrapper);
    }

    function off(event: string, listener: Listener): void {
        const eventListeners = listeners.get(event);
        if (!eventListeners) return;

        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
            eventListeners.splice(index, 1);
        }
    }

    function emit(event: string, ...args: any[]): any[] {
        const eventListeners = listeners.get(event);
        if (!eventListeners) return [];

        return eventListeners.map(listener => listener(...args));
    }

    function removeAllListeners(event?: string): void {
        if (!event) {
            listeners.clear();
        } else {
            listeners.delete(event);
        }
    }

    const emitter: EventEmitter = {
        on,
        once,
        off,
        emit,
        removeAllListeners
    };

    return emitter;
}
