type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  interface EventEntry {
    listener: Listener
    once: boolean
  }

  interface EventMap {
    [event: string]: EventEntry[]
  }

  const events: EventMap = Object.create(null)

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: false })
      return events[event].length
    },

    once(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: true })
      return events[event].length
    },

    off(event: string, listener: Listener): boolean {
      const entries = events[event]
      if (!entries) {
        return false
      }
      const index = entries.findIndex(entry => entry.listener === listener)
      if (index === -1) {
        return false
      }
      entries.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      const entries = events[event]
      if (!entries) {
        return []
      }
      const results: unknown[] = []
      const listeners = [...entries]

      for (const { listener, once } of listeners) {
        let handled = false
        try {
          results.push(listener(payload))
          handled = once
        } catch (error) {
          results.push(error as unknown)
          handled = once
        }
        if (handled) {
          const index = events[event].findIndex(entry => entry.listener === listener)
          if (index !== -1) {
            events[event].splice(index, 1)
          }
        }
      }

      return results
    },

    listenerCount(event: string): number {
      return events[event]?.length ?? 0
    }
  }
}

export { createEventEmitter }
export type { Listener, EventEmitter }
