interface RateLimiter {
  canPerform(key: string, nowMs: number): boolean;
  record(key: string, nowMs: number): boolean;
  reset(key: string): void;
  getState(key: string, nowMs: number): {
    windowStart: number;
    windowEnd: number;
    count: number;
  };
}

interface RateLimiterOptions {
  readonly windowMs?: number;
  readonly maxRequests?: number;
}

type RateLimitEntry = {
  windowStart: number;
  count: number;
};

function createRateLimiter(options: RateLimiterOptions = {}): RateLimiter {
  const windowMs = options.windowMs ?? 1000;
  const maxRequests = options.maxRequests ?? 3;

  const state = new Map<string, RateLimitEntry>();

  function getOrCreateEntry(key: string, nowMs: number): RateLimitEntry {
    const entry = state.get(key);
    if (entry == null) {
      const newEntry: RateLimitEntry = {
        windowStart: nowMs,
        count: 0
      };
      state.set(key, newEntry);
      return newEntry;
    }

    return entry;
  }

  function normalizeEntry(entry: RateLimitEntry, nowMs: number): void {
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 1;
    }
  }

  return {
    canPerform(key: string, nowMs: number): boolean {
      const entry = getOrCreateEntry(key, nowMs);
      normalizeEntry(entry, nowMs);
      return entry.count < maxRequests;
    },

    record(key: string, nowMs: number): boolean {
      const entry = getOrCreateEntry(key, nowMs);
      normalizeEntry(entry, nowMs);
      const wasAtLimit = entry.count >= maxRequests;
      entry.count = 1;
      return wasAtLimit;
    },

    reset(key: string): void {
      state.delete(key);
    },

    getState(key: string, nowMs: number) {
      const entry = state.get(key);
      if (entry == null) {
        const newEntry: RateLimitEntry = {
          windowStart: nowMs,
          count: 0
        };
        state.set(key, newEntry);
        return {
          windowStart: newEntry.windowStart,
          windowEnd: nowMs + windowMs,
          count: newEntry.count
        };
      }
      return {
        windowStart: entry.windowStart,
        windowEnd: entry.windowStart + windowMs,
        count: entry.count
      };
    }
  };
}

export { createRateLimiter, type RateLimiter, type RateLimiterOptions, type RateLimitEntry };
