interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

const limit = 3
const windowMs = 1000

export function createRateLimiter(): RateLimiter {
  const keyStates = new Map<string, {
    windowStart: number
    count: number
  }>()

  const getOrInitializeState = (key: string, nowMs: number): { windowStart: number; count: number } => {
    const existing = keyStates.get(key)
    if (!existing) {
      return { windowStart: nowMs, count: 0 }
    }

    if (nowMs - existing.windowStart >= windowMs) {
      return { windowStart: nowMs, count: 0 }
    }

    return { windowStart: existing.windowStart, count: existing.count }
  }

  const allow = (key: string, nowMs: number): boolean => {
    const state = getOrInitializeState(key, nowMs)
    if (state.count < limit) {
      state.count++
      keyStates.set(key, state)
      return true
    }
    return false
  }

  const remaining = (key: string, nowMs: number): number => {
    const state = getOrInitializeState(key, nowMs)
    return Math.max(0, limit - state.count)
  }

  const reset = (key: string): void => {
    keyStates.delete(key)
  }

  return { allow, remaining, reset }
}
