export function createTtlCache(): TtlCache {
  interface CacheEntry {
    value: unknown
    expiresAt: number
  }

  const store = new Map<string, CacheEntry>()

  function set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
    store.set(key, {
      value,
      expiresAt: nowMs + ttlMs
    })
  }

  function get(key: string, nowMs: number): unknown {
    const entry = store.get(key)
    if (!entry || nowMs >= entry.expiresAt) {
      return undefined
    }
    return entry.value
  }

  function has(key: string, nowMs: number): boolean {
    const entry = store.get(key)
    return entry !== undefined && nowMs < entry.expiresAt
  }

  function deleteKey(key: string): boolean {
    return store.delete(key)
  }

  function count(nowMs: number): number {
    let count = 0
    for (const entry of store.values()) {
      if (nowMs < entry.expiresAt) {
        count++
      }
    }
    return count
  }

  function clearCache(): void {
    store.clear()
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size: count,
    clear: clearCache
  }
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}
