        currentRateWindows = new Set();
        keys = normalizedKey;
        windows.set(normalizedKey, currentRateWindows);
      }

      // Check if window has fully elapsed
      const lastCallMs = currentRateWindows.has(nowMs.toString()) 
        ? nowMs.toString()
        : "now";

      const msSinceLast = nowMs - parseInt(lastCallMs, 10) || 0;
      let shouldClearWindow = true;

