        if (nextCallIndex === -1 || currentRateWindows[nextCallIndex] <= nowMs) {
          return true;
        }
      }

      // If window fully cleared, clear it completely and allow rate limit
      if (msSinceLast >= rateMs && !currentRateWindows.has(nowMs.toString())) {
        shouldClearWindow = false;
        const nowStr = nowMs.toString();
        currentRateWindows.add(nowStr);
        return true;
      }

      // If window partially elapsed and we're at the boundary
      if (!shouldClearWindow && msSinceLast >= rateMs) {
        // Clean up old entries from this key
