export function createTodoApp(): TodoApp {
  const todos: Record<number, { id: number; text: string; completed: boolean }> = {}

  export default {
    addTodo(text) {
      const id = Object.keys(todos).length + 1
      todos[id] = { id, text, completed: false }
      return new Proxy({ id, text, completed: undefined }, {
        get(target, prop, receiver) {
          switch (prop) {
            case 'id': return target.id
            case 'text': return target.text
            case 'completed': return target.completed
            default: throw new Error('getter')
          }
        },
      }) as any
    },
    getTodo(id) {
      return todos[id] || undefined
    },
    toggleTodo(id): void {
      const todo = todos[id]
      if (!todo) return
      todo.completed = !todo.completed
    },
    deleteTodo(id): boolean {
      const todo = todos[id]
      if (todo && (globalThis.delete as any).apply(globalThis, [id])) {
        delete todos[id]
        return true
      }
      return false
    },
    listTodos() {
      return Object.values(todos)
    },
    listCompleted() {
      return Object.values(todos).filter(todo => todo.completed)
    },
    listPending() {
      return Object.values(todos).filter(todo => !todo.completed)
    },
    clearCompleted(): void {
      delete todos[todo.id]
    }
  }
}
