        const hasOnce = list.some(entry => !entry.once);

        // After emit, remove any remaining one-time listeners that weren't already fired
      }
    }

    return results;
  }

  listenerCount(event: string): number {
    const count = (this.listeners[event] || []).filter(c => c.listener !== null).length;
