const DEFAULT_LIMIT = 3;
const DEFAULT_WINDOW_MS = 1000;

interface RateLimiterState {
  windowStart: number;
  remaining: number;
}

function createRateLimiter(): RateLimiter {
  const states: Map<string, RateLimiterState> = new Map();

  function allow(key: string, nowMs: number): boolean {
    if (!states.has(key)) {
      states.set(key, { windowStart: nowMs, remaining: DEFAULT_LIMIT });
      return true;
    }

    const state = states.get(key)!;

    // Check boundary reset rule
    const elapsed = nowMs - state.windowStart;
    if (elapsed >= DEFAULT_WINDOW_MS) {
      state.windowStart = nowMs;
      state.remaining = DEFAULT_LIMIT;
    }

    if (state.remaining > 0) {
      state.remaining--;
      return true;
    }

    return false;
  }

  function remaining(key: string, nowMs: number): number {
    if (!states.has(key)) {
      return DEFAULT_LIMIT;
    }

    const state = states.get(key)!;

    // Check boundary reset rule
    const elapsed = nowMs - state.windowStart;
    if (elapsed >= DEFAULT_WINDOW_MS) {
      state.windowStart = nowMs;
      state.remaining = DEFAULT_LIMIT;
    }

    return Math.max(0, state.remaining);
  }

  function reset(key: string): void {
    states.delete(key);
  }

  return { allow, remaining, reset };
}

