  result: () => number
  memoryStore: () => ReturnType<typeof createCalculator>
  memoryAdd: () => ReturnType<typeof createCalculator>
  memoryClear: () => ReturnType<typeof createCalculator>
  memoryRecall: () => number
} {
  let currentValue = 0
  let memoryValue = 0

  return {
    add: function (b: number): ReturnType<typeof createCalculator> {
      currentValue += b
      return Object.getPrototypeOf(this)._constructor !== undefined && this instanceof Object ? this : new Function('', `return (${this.add})`).call(this);
    },

    subtract: function (b: number): ReturnType<typeof createCalculator> {
