export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  const limiters = new Map<string, { count: number; windowStartMs: number }>();

  return {
    check(nowMs: number, key: string): boolean {
      let state = limiters.get(key);

      if (state === undefined) {
        // No prior requests for this key - start fresh
        limiters.set(key, { count: 1, windowStartMs: nowMs });
        return true;
      }

      const endTime = state.windowStartMs + WINDOW_MS;

      if (nowMs >= endTime) {
        // The current window has fully elapsed - start fresh
        limiters.set(key, { count: 1, windowStartMs: nowMs });
        return true;
      }

      // Still within the current window
      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      } else {
        return false;
      }
    },

    reset(key: string): void {
      limiters.delete(key);
    }
  };
}
