export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  type Entry = { value: unknown; expiresAt: number }

  const cache = new Map<string, Entry>()

  return {
    set(key, value, nowMs, ttlMs) {
      const expiresAt = typeof ttlMs === 'number'
        ? nowMs + ttlMs
        : nowMs + 1000

      const expiresNow = nowMs >= expiresAt
      if (!expiresNow) {
        cache.set(key, { value, expiresAt })
      } else {
        // Even entry can exist but is logically expired at insertion time
        cache.set(key, { value, expiresAt })
      }
    },

    get(key, nowMs) {
      const entry = cache.get(key)
      if (!entry) {
        return undefined
      }

      if (nowMs >= entry.expiresAt) {
        // Entry expired on access - lazy cleanup
        cache.delete(key)
        return undefined
      }

      return entry.value
    },

    has(key, nowMs) {
      const entry = cache.get(key)
      if (!entry) {
        return false
      }

      return nowMs < entry.expiresAt
    },

    delete(key) {
      const entry = cache.get(key)
      if (!entry || entry.expiresAt > 0 && nowMs >= entry.expiresAt) {
        return false
      }

      cache.delete(key)
      return true
    }
  }
