        eventListeners.splice(toRemove[j], 1)
      }

      if (eventListeners.length === 0) {
        listeners.delete(event)
      }

      return results
    },

    listenerCount(event) {
      const eventListeners = listeners.get(event)
      return eventListeners ? eventListeners.length : 0
    }
  }
