export function createEventEmitter(): EventEmitter {
  const listeners: Map<string, Listener[]> = new Map()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push(listener)
      return list.length
    },

    once(event: string, listener: Listener): number {
      const onceWrapper: Listener = (payload) => {
        listener(payload)
        off(event, onceWrapper)
      }

      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const list = listeners.get(event)!
      list.push(onceWrapper)
      return list.length
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners.has(event)) {
        return false
      }
      const list = listeners.get(event)!
      const index = list.indexOf(listener)
      if (index === -1) {
        return false
      }
      list.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners.has(event)) {
        return []
      }
      const list = listeners.get(event)!
      return [...list].map(fn => fn(payload))
    },

    listenerCount(event: string): number {
      return listeners.get(event)?.length ?? 0
    }
  }
