type RateLimiterState = {
  windowStart: number;
  requestCount: number;
};

type RateLimiter = {
  check(key: string, nowMs: number): { allowed: boolean; remaining: number };
  reset(key: string): void;
  getState(key: string, nowMs: number): { windowStart: number; count: number };
};

const WINDOW_MS = 1000;
const MAX_REQUESTS = 3;

function getAlignedWindow(nowMs: number): number {
  return Math.floor(nowMs / WINDOW_MS) * WINDOW_MS;
}

function createRateLimiter(): () => RateLimiter {
  const stateMap = new Map<string, RateLimiterState>();

  function getInstance(): RateLimiter {
    return {
      check(key: string, nowMs: number): { allowed: boolean; remaining: number } {
        const windowStart = getAlignedWindow(nowMs);

        let keyState: RateLimiterState | null = stateMap.get(key) || null;

        if (!keyState || keyState.windowStart !== windowStart) {
          keyState = { windowStart, requestCount: 0 };
          stateMap.set(key, keyState);
        }

        const remaining = MAX_REQUESTS - keyState.requestCount;
        const allowed = remaining > 0;

        if (!allowed) {
          return { allowed: false, remaining: 0 };
        }

        keyState.requestCount++;
        return { allowed: true, remaining: MAX_REQUESTS - keyState.requestCount };
      },

      reset(key: string): void {
        stateMap.delete(key);
      },

      getState(key: string, nowMs: number): { windowStart: number; count: number } {
        const windowStart = getAlignedWindow(nowMs);
        const keyState = stateMap.get(key);

        if (!keyState || keyState.windowStart !== windowStart) {
          return { windowStart, count: 0 };
        }

        return { windowStart: keyState.windowStart, count: keyState.requestCount };
      },
    };
  }

  return getInstance;
}

export { createRateLimiter };
