type Listener<TArgs extends any[]> = (...args: TArgs) => any;

interface EventEmitter {
  on<TArgs extends any[]>(event: string, listener: Listener<TArgs>): () => void;
  off<TArgs extends any[]>(event: string, listener: Listener<TArgs>): void;
  once<TArgs extends any[]>(event: string, listener: Listener<TArgs>): () => void;
  emit<TArgs extends any[]>(event: string, ...args: TArgs): any[];
}

export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Listener<any>[]> = {};

  return {
    on<TArgs extends any[]>(event: string, listener: Listener<TArgs>): () => void {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(listener);
      return () => {
        off(event, listener);
      };
    },

    off<TArgs extends any[]>(event: string, listener: Listener<TArgs>): void {
      if (!listeners[event]) {
        return;
      }
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
      }
    },

    once<TArgs extends any[]>(event: string, listener: Listener<TArgs>): () => void {
      const wrapper: Listener<TArgs> = (...args) => {
        off(event, wrapper);
        return listener(...args);
      };
      return on(event, wrapper);
    },

    emit<TArgs extends any[]>(event: string, ...args: TArgs): any[] {
      if (!listeners[event]) {
        return [];
      }
      return listeners[event].map((listener) => listener(...args));
    }
  };
}
