export function createRateLimiter() {
  interface WindowState {
    count: number;
    windowStart: number;
  }

  const windows: Map<string, WindowState> = new Map();
  const MAX_REQUESTS = 3;
  const WINDOW_SIZE_MS = 1000;

  return {
    isAllowed: (key: string, nowMs: number): boolean => {
      const state = windows.get(key);

      if (!state || nowMs - state.windowStart >= WINDOW_SIZE_MS) {
        windows.set(key, {
          count: 1,
          windowStart: nowMs
        });
        return true;
      }

      if (state.count < MAX_REQUESTS) {
        state.count++;
        return true;
      }

      return false;
    },
    reset: (key: string): void => {
      windows.delete(key);
    }
  };
