function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state: Record<string, { windowStart: number; count: number }> = {}

  function allow(key: string, nowMs: number): boolean {
    const entry = state[key]
    if (!entry || nowMs - entry.windowStart >= windowMs) {
      state[key] = { windowStart: nowMs, count: 1 }
      return true
    }
    if (entry.count < limit) {
      entry.count++
      return true
    }
    return false
  }

  function remaining(key: string, nowMs: number): number {
    const entry = state[key]
    if (!entry || nowMs - entry.windowStart >= windowMs) {
      return limit
    }
    return Math.max(0, limit - entry.count)
  }

  function reset(key: string): void {
    delete state[key]
  }

  return { allow, remaining, reset }
}

export { createRateLimiter }

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
