export function createTtlCache(): TtlCache {
  const cache = new Map<string, { value: unknown; expiresAt: number }>()
  const DEFAULT_TTL = 1000

  return {
    set(key, value, nowMs, ttlMs = DEFAULT_TTL) {
      const expiresAt = nowMs + ttlMs
      cache.set(key, { value, expiresAt })
    },
    get(key, nowMs) {
      const entry = cache.get(key)
      if (entry && nowMs < entry.expiresAt) {
        return entry.value
      }
      return undefined
    },
    has(key, nowMs) {
      const entry = cache.get(key)
      return entry !== undefined && nowMs < entry.expiresAt
    },
    delete(key) {
      return cache.delete(key)
    },
    size(nowMs) {
      let count = 0
      for (const [key, entry] of cache) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },
    clear() {
      cache.clear()
    },
  }
}

