export function createEventEmitter<EventName extends string>() {
  type Listener = (...args: unknown[]) => unknown;
  type ListenerEntry = { listener: Listener; once: boolean };

  type EventMap = Map<EventName, ListenerEntry[]>;
  type Unregister = { eventName: EventName; index: number };

  const events: EventMap = new Map();
  let nextId = 0;

  const emitter = {
    on(eventName: EventName, listener: Listener): Unregister {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ listener, once: false });
      return { eventName, index: nextId++ };
    },

    once(eventName: EventName, listener: Listener): Unregister {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ listener, once: true });
      return { eventName, index: nextId++ };
    },

    off(unregister: EventName | Unregister): void {
      const eventName = typeof unregister === 'string'
        ? unregister
        : unregister.eventName;
      const index = typeof unregister === 'string'
        ? -1
        : unregister.index;

      const listeners = events.get(eventName);
      if (!listeners) return;

      if (index === -1) {
        events.delete(eventName);
      } else {
        listeners.splice(index, 1);
        if (listeners.length === 0) {
          events.delete(eventName);
        }
      }
    },

    emit(eventName: EventName, ...args: unknown[]): unknown[] {
      const listeners = events.get(eventName);
      if (!listeners) return [];

      const results: unknown[] = [];
      const removed: Unsubscribe[] = [];

      listeners.forEach((entry, i) => {
        let result: unknown;
        try {
          result = entry.listener(...args);
        } catch {
          result = undefined;
        }

        results.push(result);

        if (entry.once) {
          removed.push({ eventName, index: i });
        }
      });

      removed.forEach(({ eventName, index }) => {
        const listeners = events.get(eventName);
        if (listeners) {
          listeners.splice(index, 1);
          if (listeners.length === 0) {
            events.delete(eventName);
          }
        }
      });

      return results;
    },

    clear(): void {
      for (const key of events.keys()) {
        events.delete(key);
      }
    }
  };

  return emitter;
}
