export function createRateLimiter(): RateLimiter {
  const requests = new Map<string, { timestamps: number[]; windowStart: number }>();

  const getTimestamps = (key: string, nowMs: number) => {
    const entry = requests.get(key);
    if (!entry || nowMs - entry.windowStart > 1000) {
      requests.set(key, { timestamps: [nowMs], windowStart: nowMs });
      return { timestamps: [nowMs], windowStart: nowMs };
    }
    return entry;
  };

  const canRequest = (key: string, nowMs: number): boolean => {
    const { timestamps } = getTimestamps(key, nowMs);
    if (timestamps.length < 3) {
      timestamps.push(nowMs);
      return true;
    }
    return false;
  };

  const reset = (key: string): void => {
    requests.delete(key);
  };

  return { canRequest, reset };
}
