interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

interface KeyState {
  count: number
  windowStart: number
}

const limit = 3
const windowMs = 1000
const keyStates = new Map<string, KeyState>()

function createRateLimiter(): RateLimiter {
  return {
    allow(key: string, nowMs: number): boolean {
      let state = keyStates.get(key)

      if (!state) {
        state = {
          count: 1,
          windowStart: nowMs
        }
        keyStates.set(key, state)
        return true
      }

      const timeSinceStart = nowMs - state.windowStart

      if (timeSinceStart >= windowMs) {
        state.count = 1
        state.windowStart = nowMs
        keyStates.set(key, state)
        return true
      }

      if (state.count < limit) {
        state.count++
        keyStates.set(key, state)
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      const state = keyStates.get(key)

      if (!state) {
        return limit
      }

      const timeSinceStart = nowMs - state.windowStart

      if (timeSinceStart >= windowMs) {
        return limit
      }

      return Math.max(0, limit - state.count)
    },

    reset(key: string): void {
      keyStates.delete(key)
    }
  }
}

export { createRateLimiter, RateLimer, RateLimiter }
