  expiresAt: number;
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

function createTtlCache(): TtlCache {
  const cache: Map<string, CacheEntry> = new Map();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = ttlMs === 0 ? nowMs : nowMs + (ttlMs ?? 1000);
      cache.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key);
      if (!entry) {
        return false;
      }
      return nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return cache.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      for (const entry of cache.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },

    clear(): void {
      cache.clear();
    }
  };
}

