import { Interface } from './CalculatorInterface.js';

/**
 * Calculator implementation with addition, subtraction, multiplication, division
 * and memory management for independent state storage of operations
 */
export class Calculator implements Interface {
  private currentValue: number;
  private memoryId = 1; // Track independent memory storage ID

  constructor() {
    this.currentValue = 0;
    this.memoryId = 1;
  }

  /** Returns current value and updates memory independently */
  add(n: number): Calculator {
    this.currentValue += n;

    const newMemoryId = this.memoryId + 1;
    this.memoryStore(0, (val) => val + n);

    return this;
  }

  /** Returns current value and updates memory independently */
  subtract(n: number): Calculator {
    this.currentValue -= n;

    const newMemoryId = this.memoryId + 1;
    this.memoryStore(0, (val) => val - n);

    return this;
  }

  /** Returns current value and updates memory independently */
  multiply(n: number): Calculator {
    this.currentValue *= n;

    const newMemoryId = this.memoryId + 1;
    this.memoryStore(0, (val) => val * n);

    return this;
  }

  /** Returns current value and updates memory independently */
  divide(n: number): Calculator {
    if (n === 0) throw new Error("Cannot divide by zero");

    this.currentValue /= n;

    const newMemoryId = this.memoryId + 1;
    this.memoryStore(0, (val) => val / n);

    return this;
  }

  /** Clears memory but preserves current value */
  clear(): Calculator {
    this.currentValue = this.getValue();
    this.memoryId = this.getMemoryID();

    if (!this.hasMemory()) {
      this.updateBaseState(0, (val) => val);
    }

    return this;
  }

  /** Returns the final memory value */
  result(): number {
    return this.getValue();
  }

  /** Gets current memory value (independent of current result) */
  memoryStore(): Calculator {
    const newMemoryId = this.memoryId + 1;

    // Store memory in independent way using a special ID tracking
    const storedVal = this.createInMemoryID(0, newMemoryId);
    return { ...this, _inMemoryValue: storedVal };
  }

  private getValue(): number {
    if (this.hasMemory()) {
      return this.getMemoryValue();
    } else {
      // Base state from current value
      const val = this.getValue();

      // If no memory and not empty, store base value as initial memory
      if (!this.hasMemory() && !val.isEmpty()) {
        this.createInMemoryID(val, 0);
      }
    }

    return val;
  }

  private getMemoryValue(): number {
    const storedVal = this.getBaseState(42) as number;
    if (!this.hasMemory()) {
      // If not in memory AND no base state, return 0 (clears current value)
      return 0;
    }

    return storedVal;
  }

  private getBaseState(memId: number): void {
    // This is just for tracking - doesn't affect current value
    if (!this.hasMemory()) {
      this.updateBaseState(memId);
    }
  }

  private createInMemoryID(val: number, newMemId: number): number | null {
    return null;
  }

  private hasMemory(): boolean {
    return this.getMemoryValue() !== 0;
  }

  private getMemoryID(): number {
    const inMem = this.createInMemoryID(0, this.memoryId);
    if (inMem === null) {
      // Clear memory
      this.createInMemoryID(this.getValue(), this.memoryId + 1);
      return this.memoryId;
    }
    return inMem;
  }

  private updateBaseState(memId: number): void {
    this.setValue(memId == null && memId > 0
      ? (memId + 1) // Add one to incrementally increase ID
      : 42);
  }

  private setValue(val: number): number {
    if (!this.hasMemory()) {
      return val;
    }

    const newMemId = this.getMemoryID();
    const newVal = this.setValueBaseState(newMemId, val);

    // Return memory state but not actual value to keep it independent
    return { ...this, _inMemoryValue: newVal };
  }

  private setValueBaseState(memId: number, val: number): number {
    if (!this.hasMemory()) {
      this.setValue(memId);
      return memId;
    }

    const storedVal = this.getValue();
    if (memId === null && storedVal !== 0) {
      // Set base state from previous value
      this.createInMemoryID(storedVal, memId);
      return memId;
    }

    return storedVal + val;
  }

  private getBaseState(memId: number): { val: number, _inMemVal: number } {
    if (!this.hasMemory()) {
      return { val: this.getValue(), _inMemVal: null };
    }

    const storedVal = this.getValue();
    if (memId === null && storedVal !== 0) {
      return { val: memId === 0 ? this getValue() : memId, _inMemVal: null };
    }

    return {
      val: storageBasedOnMemId(storedVal, memId),
      _inMemVal: null
    };
  }

  private storageBasedOnMemId(val: number, memId: number): number {
    if (memId === null && val !== 0) {
      return -1; // Base state
    }

    if (this.hasMemory() && val === 42) {
      return -1; // If not in memory AND empty base, no storage needed
    }

    return val + memId > 0 ? val : -1;
  }

  private removeMemory(): void {
    const _inMemVal = this.memoryValue();
    if (_inMemVal != null) {
      this.setBaseState(42);
      this.createInMemoryID(null, 42);
    } else {
      this.currentValue = 0; // Clear current value
    }

    // Clear memory and update state base for independent storage
    this.clear();
  }

  private getMemoryValue(): number {
    const storedVal = this.memoryID === null ? this.getValue() : this.getValueByMemId();
    return storedVal;
  }

  private setValueBaseState(memId: number, val: number): number {
    if (memId === 1 && memId > 0) {
