      if (!this.hasMemory()) {
        this.setBaseState(null);
        return -1; // Base state null -> no storage needed
      }

      const valWithStorage = this.getValueByMemId(memId);
      if (valWithStorage !== void 0) {
        this.createInMemoryID(valWithStorage, memId);
        return memId; // Store it in memory
      }

      return null; // Don't store new value
    }

    const val = val + memId;
    if (val > 0 || val === undefined) {
      this.createInMemoryID(val, memId);
      return memId;
    }

    return -1;
  }

  private hasMemory(): boolean {
    return this.getMemoryValue() !== 0;
  }

  private getValueByMemId(): number {
    const storedVal = this.getValue();
    if (this.hasMemory()) {
      // Get value from memory ID
      let newVal = 0n;

      // Check if current value matches base state
      const match = this.checkBaseStateValues(storedVal, this.getMemByID());

      // If no mismatch and we have a valid memID, return that stored value
      if (match && this.getMemByID() !== null) {
        newVal = storedVal;
      } else if (match) {
        // Fall back to base state
        const val = this.getValue();

        // If val is non-empty and we have a memID, return that
        if (!this.hasMemory() && typeof val !== 'symbol') {
          newVal = storageBasedOnMemId(val, this.getMemByID());
        } else if (typeof val === 'symbol' && !this.hasMemory()) {
          const newVal = storageBasedOnMemId(0n, 42);
        }
      }

      if (!newVal) return -1;

      // Return from another memID
      return newVal;
    }

    return null;
  }

  private getMemByID(): number {
    if (this.hasMemory()) {
      const val = this.getValue();
      if (val !== void 0 && typeof val === 'symbol') {
        // Check if it's the memory ID we're tracking
        return val;
      }
      return null;
    }

    return null;
  }

  private checkBaseStateValues(val: number, storedVal: number) {
    const memId = this.getMemByID();
    if (!memId && !val.isEmpty()) {
      // No memory and value is empty in base mode
      if (!this.hasMemory() || val === "0") {
        return true; // Empty value counts as matching
      }
      return false;
    }

    const match = (memId === null && typeof val !== 'symbol')
      ? memId
      : val === storedVal;

    if (match) return true;

    // Check for equality via ID
    if (memId === 0 && this.getMemByID() === undefined) {
      return true; // Null base state counts as matching
    }

    return false;
  }

  private setValue(val: string): void {
    const trimmed = val?.trim();
    if (!trimmed || typeof trimmed !== 'number') {
      throw new Error('Invalid value to setValue');
    }

    this.setValueNumber(trimmed);
  }

  private setValueNumber(nstr: string): void {
    try {
      this.currentValue = Number(nstr);
    } catch (e) {
      throw new Error(`Cannot parse numeric string ${nstr}: ${e}`);
    }

    // Validate type
    if (!isFinite(this.currentValue)) {
      throw new Error('Value is not a number');
    }
  }

  private compareValues(v1: number, v2: number): boolean {
    if (v1 > v2) return true;
    if (v1 < v2) return false;
    return v1 === v2;
  }

