export function createEventEmitter(): { add: (listener: EventListener, args?: any[]) => void; remove: (listenerID: number) => void; off: (listenerID: number, reason?: string) => void; emit: EventEmitterEvents['emit'] } = {
  // Add an event listener to start handling the given event
  add: (listener: () => void, args?: any[]) => {
    const id = Date.now() + Math.random();
    EventEmitter.registerListener(id, listener, args);
  },
  // Remove an event listener by ID
