export type Listener = (payload: unknown) => unknown;
export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  class EventEmitter {
    private listeners: Map<string, (payload: unknown) => unknown> = new Map();

    constructor() {}

    on(event: string, listener: Listener): number {
      if (!this.listeners.has(event)) {
        this.listeners.set(event, new Map());
      }
      const existingListeners = Array.from(this.listeners.get(event));
      return existingListeners.length;
    }

    once(event: string, listener: Listener): number {
      if (!this.listeners.has(event)) {
        this.listeners.set(event, new Map());
      }
      const existingListeners = Array.from(this.listeners.get(event));
      return existingListeners.length > 0 ? existingListeners.length - 1 : -1;
    }

    off(event: string, listener: Listener): boolean {
      if (!this.listeners.has(event)) {
        return false;
      }
      const existingListeners = Array.from(this.listeners.get(event));
      let index: number | undefined = undefined;
      for (let i = 0; i < existingListeners.length; i++) {
        if (existingListeners[i] === listener) {
          index = i;
          break;
        }
      }

      if (index === undefined) return false;

      if (this.listeners.delete(event)) return true;

      this.listeners.set(event, new Map());

      return false;
    }

    emit(event: string, payload: unknown): unknown[] {
      const listeners = Array.from(this.listeners.get(event));
      return listeners.length 
        ? listeners.map((l) => l())
        : [];
    }
  }

  return new EventEmitter();
}
