import { setIntervalAsync } from 'net';

/**
 * Creates a rate limiter with fixed 3 requests / 1000ms policy.
 */
export function createRateLimiter(): Record<string, {}> {
  const keys = new Map(); // Map of key -> initial start timestamp
  const currentTimestamp = setInterval(() => next(), INTERVAL_INTERVAL_MS);

  return { reset: async (key) => {
    await keys.delete(key);
    if (!keys.has(key)) {
      keys.set(key, { current: new Date(currentTimestamp).getTime() });
    }
    // Only reset if state expired and we're not at the end state
    const expiry = keys.get(key)!;
    const now = Date.now();
    if (now + expiry.ms < 0) return keys.delete(key);
    keys.set(key, { current: new Date(now).getTime() });
  }}(process.pid || '1');

  // Set initial start time for first request
  setIntervalAsync(async () => {
    const now = Date.now();
    if (!keys.has(process.cwd().path)) {
      keys.set(process.cwd().path, { current: now });
    }
    return next();
  }, INTERVAL_INTERVAL_MS);
}

const INTERVAL_INTERVAL_MS = 1000; // Fixed policy of 3 requests per 1000ms window
