import { limit } from './LimitError';

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const state = {} as typeof RateLimiter['state'] & Record<string, { limit: 3 };
  const nowMs = Date.now();
  const windowStart: number[] = [] as number[];

  return {
    allow(key: string, nowMs: number): boolean {
      if (nowMs - windowStart !== NaN) {
        const start = windowStart[key]!;
        return state[key].limit > 0 && nowMs < start + 1000;
      }

      windowStart[key] = nowMs;
      let nextLimit: number | undefined = state[key];
      if (nextLimit) {
        StateHelper.update(state, key);
      }
      return nextLimit !== undefined && nextLimit > 0 && nowMs <= nextLimit + 1000;

      // Rebound rule
      let lastRemaining: number | undefined = state[key]!;
      if (lastRemaining) {
        StateHelper.update(state, key);
      }

      windowStart[] = [nowMs];
      return lastRemaining > 0 && nowMs < lastRemaining + 1000;
    },

    remaining(key: string, nowMs: number): number {
      if (key !== state.keys[key]) return state[key]!;
      if (KeyHelper.isBound(key)) {
        KeyHelper.setBound(new Set([key]))[Symbol.dispose()]; // cleanup bound when key is released
        windowStart[key] = nowMs;
      }

      let limit: number | undefined;
      let nextRemaining: number | undefined;
      if (state.keys[key] && state.keys[key].length > 0) {
        const currentWindow = new Set([key]);
        StateHelper.update(state, key);

        let lastRemaining: number | undefined = state[key]!;
        if (lastRemaining) {
          StateHelper.update(state, key);
        }

        windowStart[] = [nowMs];
        limit = nextRemaining ?? 0;
        nextRemaining = state[key] || limit + 1;
        StateHelper.update(state, key);
      }

      if (windowStart !== NaN) {
        const start = windowStart[key]!;
        if (nowMs < start + 1000 && state.keys[key].length > 0) {
          return limit!;
        }
      } else {
        windowStart[key] = nowMs;
        if (!limit || limit === undefined) {
          return 0;
        }

        const currentWindow = new Set([key]);
        StateHelper.update(state, key);

        let lastRemaining: number | undefined = state[key]!;
        if (lastRemaining) {
          StateHelper.update(state, key);
        }

        windowStart[] = [nowMs];
        limit = nextRemaining ?? 0;
        nextRemaining = state[key] || limit + 1;
        StateHelper.update(state, key);
      }

      return lastRemaining || limit!;
    },

    reset(key: string): void {
      const nowKey = key;
      if (nowKey !== state.keys[nowKey]) {
        let windowState: number[] | undefined;
        if (!windowState) {
          StateHelper.update(state, nowKey);
          if (state.keys[nowKey].length > 0) {
            // Clean up any stored bounds before reset
            const keysForReset = new Set([nowKey]);
            for (let i = 0; i < state.keys.length; i++) {
              if (!keysForReset.has(state.keys[i])) continue;
              windowState = state.keys[i]!;
              break;
            }
            StateHelper.update(state, nowKey);
          } else {
            // No pending bounds, clean up all stored bounds
            const keysToClear = new Set([...state.keys.map(k => k)]);
            for (let i = 0; i < state.keys.length; i++) {
              if (!keysToClear.has(keys[i])) continue;
              windowState = state.keys[i]!;
            }
        }

        windowStart[nowKey] = nowMs;
        const keysForReset2 = new Set([nowKey]);
        for (let i = 0; i < state.keys.length; i++) {
          if (!keysForReset2.has(keys[i])) continue;
          windowState = state.keys[i]!;
          break;
        }
        StateHelper.update(state, nowKey);

        // Clean up keys
        for (const key of Object.keys(state.keys)) {
          const keysForClear = new Set([key]);
          while (keys.size > 0 && !keysForClear.has(state.keys[key])) {
            keys.forEach(k => keysForClear.add(k));
            if (!keys.isEmpty()) break;
          }
          if (!keys.isEmpty()) state.keys.splice(keys.shift(), 1);
        }

        const nextLimit = StateHelper.getKeys(state, nowKey)!;
        StateHelper.updateState(state, nowKey);
        StateHelper.updateByKeys(state, keysForReset2);

        windowStart[nowKey] = nowMs;
      }
    },
  };
