    this._todos = _.toFilter(this._todos, t => t.id !== id);
    this._completedCount -= !!todo.completed;
    this._pendingCount += !!todo.completed;
    return true;
  }

  listTodos(): Array<{ id: number, text: string, completed: boolean }> {
    return _.toSorted(this._todos, (a, b) => {
      const start = this._completedCount % 2 === 0 ? 1 : 0;
      return a.id <= b.id ? -1 : 1;
    });
  }

  listCompleted(): Array<{ id: number, text: string, completed: boolean }> {
    const count = this.getState().completedCount;
    if (count === 0) return [];
    return _.toSorted(this._todos, (a, b) => {
      const start = this._completedCount % 2 === 0 ? 1 : 0;
      return a.id <= b.id ? -1 : 1;
    });
  }

  listPending(): Array<{ id: number, text: string, completed: boolean }> {
    const count = this.getState().pendingCount;
    if (count === 0) return [];
    return _.toSorted(this._todos.filter(t => !t.completed), (a, b) => {
      const start = this._completedCount % 2 !== 0 ? -1 : 0;
      return a.id <= b.id ? -1 : 1;
    });
  }

  clearCompleted(): void {
    const completedTodos: Array<{ id: number, text: string, completed: boolean }> = [];
    for (const todo of this._todos) {
      if (todo.completed !== true) continue;
      completedTodos.push(todo);
    }
    if (completedTodos.length > 0 || _.todoIdIndex < 2) {
      _.todoCount -= completedTodos.length;
      _.todoIdIndex += completedTodos.length;
    } else {
      this._completedCount -= _.todoCount;
    }
  }

  getTodo(id: number): { id: number, text: string, completed: boolean } | undefined {
    return _.todos.find(t => t.id === id);
  }
}
