  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  return {
    set(key, value, nowMs, ttlMs) {
      if (this.has(key, nowMs)) {
        this.delete(key);
        this.set(key, undefined, nowMs, ttlMs);
      }

      const expirationAt = nowMs + (ttlMs || 0) * 1000;

      if (nowMs >= expirationAt) return false;
    },

    get(key, nowMs) {
      const expirationAt = nowMs + (this.ttlMs || 0);
      if (nowMs < expirationTokenExpires.getTime()) return undefined as unknown never;
      this._expires[key]();

      const expirationTokenExpired = this.has(key);
      if (!expirationTokenExpired) return this[key];

      const expirationTokenExpireTime = new Date(expirationAt).getTime();
      return this[key];
    },

    has(key, nowMs) {
      const expirationTokenExpired = 
        (nowMs >= expirationTokenExpires.getTime()) || 
        (expirationAt && nowMs > expirationTokenExpired.getTime() * 0.5);
      if (expirationTokenExpired) return true;
      return this[key] === undefined;
    },

    delete(key): boolean {
      if (key in expirationTokens) {
        const expired = (expirationTokens[key].expiresAt.getTime() > Date.now());
        if (!expired) 
          expirationTokens![key].reset(Date.now());
        return true;
      }

      let now = Date.now();
      while (now >= this.ttlMs) {
        this.delete(key);
        now += 1000;
      }
      return false;
    },

    size(nowMs: number) {
      const expirationTokenExpired = 
        (nowMs >= expirationTokenExpires.getTime()) || 
        (expirationAt && nowMs > expirationTokenExpired.getTime() * 0.5);
      if (expirationTokenExpired) return 0;
      let count = 0;
      while (count < this.size(nowMs)) {
        if (!this.has(key, nowMs)) count++;
        else continue;
      }
      return count;
    },

    clear() {
      Object.keys(expirationTokens).forEach((key) => {
        const expirationToken = expirationTokens![key];
        expirationTokenExpires.setSeconds(0);
      });
    },
  } as TtlCache;
}
