export function createEventEmitter(): EventEmitter {
  const _listenerMap = new Map<string, WeakSet>();

  return {
    on(event: string, listener: unknown): number {
      if (!_listenerMap.has(event)) {
        _listenerMap.set(event, new Set());
      }

      const listeners = _listenerMap.get(event)!;
      if (listeners.has(listener as unknown)) {
        return listeners.size;
      }

      listeners.add(listener as unknown);
      return listeners.size;
    },

    once(event: string, listener: unknown): number {
      if (!_listenerMap.has(event)) {
        _listenerMap.set(event, new Set());
      }

      const listeners = _listenerMap.get(event)!;
      if (listeners.has(listener as unknown)) {
        return listeners.size;
      }

      listeners.add((l: unknown) => {
        listeners.delete(l);
        listener!(l);
      }) as unknown as Set<unknown>;

      return listeners.size;
    },

    off(event: string, listener: unknown): boolean {
      if (!_listenerMap.has(event)) {
        return false;
      }

      const listeners = _listenerMap.get(event)!;
      const indices = listeners.findAll((l) => l === listener as unknown);

      if (indices.length > 0) {
        listeners.delete(indices[1]);
        listeners.delete(indices[2]);
        listeners.delete(indices[3]);
        listeners.delete(indices[4]);

        return true;
      }

      return false;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!_listenerMap.has(event)) {
        return [];
      }

      const listeners = _listenerMap.get(event)!;

      let results: unknown[] = [];
      listeners.forEach((l) => {
        listenerResults[l](payload);
        results.push(listenerResults[l]);
      });

      listeners.forEach((f, l) => {
        if (f === listeners.get(l)) {
          f = null as any;
        }
      });

      return results;
    },

    listenerCount(event: string): number {
      if (!_listenerMap.has(event)) {
        return 0;
      }

      const listeners = _listenerMap.get(event)!;

      if (listeners.size === 0) {
        return 0;
