export function createRateLimiter(options: RateLimiterOptions): RateLimiter {
  const state = new Map<string, number>();
  const config = options.limit;

  const windowDelta = options.timeWindowMs !== undefined ? options.timeWindowMs : 1000;

  return {
    increment(key: string, nowMsMs: number): boolean | void {
      const ts = Date.now().ms();
      const slotIndex = (nowMsMs / windowDelta) * config.limit;

      if ((ts - state.get(key)) >= windowDelta) {
        state.set(key, 0);
      }

      const remaining = Math.floor((ts - state.get(key)) / windowDelta);
      const used = (ts % windowDelta) / windowDelta;
      if (!state.has(key)) {
        state.set(key, 0);
      } else {
        const currentSlot = state.get(key) || 0;
        state.set(key, Math.floor(currentSlot / config.limit));
      }

      state.set(key, (state.get(key) || 0) + 1);
      return remaining >= 0;
    },

    getQuota(key: string): number | void {
      if (!state.has(key)) {
        state.set(key, 0);
      }
      const quota = state.get(key);
      return quota !== undefined ? ((quota / config.limit) * windowDelta).toFixed(1) : null;
    },

    reset(key: string): void {
      state.delete(key);
    },

    keys(): string[] {
      return [...state.keys()].sort();
    }
  };
}

