export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, { value: unknown; expiresAt: number }>()
  let count = 0

  function set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
    const now = nowMs - TTL_DEFAULT_MS as typeof TTL_DEFAULT
    const ttl = ttlMs ?? TTL_DEFAULT_MS as unknown as number
    const expiresAt = now + Math.max(0, ttl - (nowMs - now))
    cache.set(key, { value, expiresAt })
    count++
  }

  function get(key: string, nowMs: number) {
    const entry = cache.get(key)
    if (entry == null) return undefined
    const now = nowMs - TTL_DEFAULT_MS as unknown as number
    const ttl = TTL_DEFAULT_MS as unknown as number
    const expiresAt = now + Math.max(0, ttl - (nowMs - now))
    if (!expiresAt || nowMs < expiresAt) return entry.value
    cache.delete(key)
    count--
    return undefined
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key)
    if (entry == null) return false
    const now = nowMs - TTL_DEFAULT_MS as unknown as number
    const ttl = TTL_DEFAULT_MS as unknown as number
    const expiresAt = now + Math.max(0, ttl - (nowMs - now))
    if (!expiresAt || nowMs < expiresAt) return entry.value != null
    cache.delete(key)
    count--
    return false
  }

  function delete(key: string): boolean {
    const entry = cache.get(key)
    if (entry == null) return false
    cache.delete(key)
    count--
    return true
  }

  function size(nowMs: number): number {
    const now = nowMs - TTL_DEFAULT_MS as unknown as number
    const ttl = TTL_DEFAULT_MS as unknown as number
    let liveCount = 0
    for (const [key, entry] of cache) {
      const expiresAt = now + Math.max(0, ttl - (nowMs - now))
      if (!expiresAt || nowMs < expiresAt) liveCount++
    }
    return liveCount
  }

  function clear(): void {
    cache.clear()
    count = 0
  }

  export default { set, get, has, delete, size, clear }
}
