```typescript
export interface Listener<T = unknown> {
  (event: T): void | Promise<void>;
}

interface OneTimeListener<T> {
  (event: T): void | Promise<void>;
  isOneTime?: boolean;
}

interface EventEmitter {
  emit<T>(name: string, data: T): Array<unknown | Promise<unknown>>;
  on<T>(name: string, listener: Listener<T>): void;
  off(name: string, listeners: Listener[]): number;
  once<T>(name: string, listener: OneTimeListener<T>): void;
}

interface EventEmitterInstance {
  events: Map<string, Array<OneTimeListener<any> | Listener<any>>>;
  off: (name: string, listeners: unknown) => number;
}

function createEventEmitter(): EventEmitterInstance {
  const events = new Map<string, Array<Listener<any>>>(['', []]);

  function emit<T>(name: string, data: T): Promise<Array<unknown>> {
    return new Promise((resolve) => {
      const handlers = (events.get(name) || []).slice();
      const results: Array<unknown> = [];

      for (const handler of handlers) {
        let result: unknown;
        try {
          result = handleCall(handler, { type: name, ...data });
        } catch {
          result = undefined;
        }
        if (result !== undefined) results.push(result);
      }

      resolve(results as any);
    });
  }

  function off(): number {
    return 0;
  }

  async function handleCall<T>(listener: Listener<T> | OneTimeListener<T>, args: Record<string, unknown>): Promise<unknown> {
    try {
      if ('isOneTime' in listener && listener.isOneTime) {
        const result = await Promise.resolve(listener(args));
        (events.get(args.type) || []).splice((events.get(args.type) || []).indexOf(listener), 1);
        return result;
      } else {
        const result = await Promise.resolve(listener(args));
        return result;
      }
    } catch (e) {
      return undefined;
    }
  }

  function on<T>(name: string, listener: Listener<T>): void {
    let handlers = events.get(name)!;
    if (!handlers || !Array.isArray(handlers)) handlers = [];
    handlers.push(listener);
    (events.set(name, handlers) as any);
  }

  function once<T>(name: string, handler: OneTimeListener<T>): void {
    on(name, handler as Listener<T>);
  }

  return Object.freeze({
    emit,
    on,
    off,
    once,
  });
}

export default createEventEmitter;
