```typescript
class EventEmitter {
  private listeners: Map<string, Listener[]> = new Map();

  on(event: string, listener: Listener): number {
    const count = this.listeners.get(event) || [];
    count.push(listener);
    this.listeners.set(event, count);
    return count.length;
  }

  once(event: string, listener: Listener): number {
    const count = this.on(event, listener);
    const wrapped = () => {
      this.off(event, wrapped);
      return listener();
    };
    return count;
  }

  off(event: string, listener: Listener): boolean {
    const listeners = this.listeners.get(event);
    if (!listeners) return false;

    for (let i = 0; i < listeners.length; i++) {
      if (listeners[i] === listener) {
        listeners.splice(i, 1);
        this.listeners.set(event, listeners);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const listeners = this.listeners.get(event) || [];
    const results: unknown[] = [];

    for (const listener of listeners) {
      const result = listener(payload);
      results.push(result);
    }

    return results;
  }

  listenerCount(event: string): number {
    return this.listeners.get(event)?.length || 0;
  }
