function createRateLimiter(): RateLimiter {
  const quotas: Record<string, { requests: number; windowStart: number }> = {};

  function isAllowed(key: string, nowMs: number): boolean {
    if (!quotas[key]) {
      quotas[key] = { requests: 0, windowStart: nowMs };
      return true;
    }

    const windowEnd = nowMs + 1000;
    const lastCheckTime = quotas[key].windowStart;

    if (nowMs >= windowEnd) {
