```typescript
interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  const rateLimiters = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!rateLimiters.has(key)) {
        rateLimiters.set(key, { count: 0, windowStart: nowMs });
      }

      const entry = rateLimiters.get(key)!;
      const elapsedMs = nowMs - entry.windowStart;

      if (elapsedMs >= windowMs) {
        rateLimiters.set(key, { count: 0, windowStart: nowMs });
      }

      if (entry.count < limit) {
        entry.count += 1;
        return true;
      } else {
        return false;
      }
    },

    remaining(key: string, nowMs: number): number {
      if (!rateLimiters.has(key)) {
        rateLimiters.set(key, { count: 0, windowStart: nowMs });
      }

      const entry = rateLimiters.get(key)!;
      const elapsedMs = nowMs - entry.windowStart;

      if (elapsedMs >= windowMs) {
        return limit;
      }

      const used = Math.max(0, entry.count);
      return Math.max(0, limit - used);
    },

    reset(key: string): void {
      rateLimiters.delete(key);
    }
  };
}
