export function createTtlCache(): TtlCache {
  const entries = new Map<string, Entry>()

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number) {
      const expiresAt = nowMs + (ttlMs ?? 1000)
      entries.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry) return undefined

      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return undefined
      }

      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      if (!entry) return false

      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return false
      }

      return true
    },

    delete(key: string): boolean {
      return entries.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const [k, e] of entries) {
        if (nowMs < e.expiresAt) {
          count++
        }
      }
      return count
    },

    clear() {
      entries.clear()
    }
  }
}

