export function createEventEmitter() {
  const events: Map<string, Array<(eventArg: unknown[]) => void>> = new Map()

  return {
    on(eventName: string, listener: (eventArg: unknown[]) => void) {
      if (!events.has(eventName)) {
        events.set(eventName, [])
      }
      const listeners = events.get(eventName)!

      // Check for duplicate and remove it, then add the new one
      const idx = listeners.findIndex(l => l === listener)
      if (idx >= 0) {
        listeners.splice(idx, 1)
      }
      listeners.push(listener)
    },

    once(eventName: string, listener: (eventArg: unknown[]) => void) {
      if (!events.has(eventName)) {
        events.set(eventName, [])
      }

      const listeners = events.get(eventName)!

      // Remove any duplicate one-time listeners from this exact function reference
      const existingIdx = listeners.findIndex(l => l === listener)
      if (existingIdx >= 0) {
        listeners.splice(existingIdx, 1)
      }

      // Wrap to handle auto-removal
      const wrappedListener: (eventArg: unknown[]) => void = function (...args: unknown[]) {
        listeners.splice(listeners.indexOf(wrappedListener), 1)
        return listener.apply(this!, args)
      }

      listeners.push(wrappedListener)
    },

    off(eventName: string, listener?: (eventArg: unknown[]) => void) {
      const listeners = events.get(eventName)
      if (!listeners) return

      if (listener === undefined) {
        // Remove all listeners for this event
        events.set(eventName, [])
      } else {
        // Remove only the matching listener
        const idx = listeners.findIndex(l => l === listener)
        if (idx >= 0) {
          listeners.splice(idx, 1)
        }
      }
    },

    emit(eventName: string, ...args: unknown[]) {
      const listeners = events.get(eventName) || []
      return listeners.map(listener => listener.apply(undefined!, args))
    }
  }
}
