```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Map<Listener, number>>()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, new Map())
      }
      if (!listeners.get(event)!.has(listener)) {
        listeners.get(event)!.set(listener, 0)
      }
      const current = listeners.get(event)!.get(listener)! + 1
      listeners.get(event)!.set(listener, current)
      return current
    },

    once(event: string, listener: Listener): number {
      const wrapped = (...args: unknown[]) => {
        try {
          listener(...args)
        } finally {
          if (listeners.has(event)) {
            listeners.get(event)!.delete(listener)
            const set = listeners.get(event)!
            if (set.size === 0) {
              listeners.delete(event)
            }
          }
        }
      }
      return this.on(event, wrapped as Listener)
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = listeners.get(event)
      if (!eventListeners || !eventListeners.has(listener)) {
        return false
      }
      const count = eventListeners.get(listener) || 0
      if (count === 1) {
        eventListeners.delete(listener)
        if (eventListeners.size === 0) {
          listeners.delete(event)
        }
      } else {
        eventListeners.set(listener, count - 1)
      }
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners.has(event)) {
        return []
      }

      const results: unknown[] = []
      const eventListeners = listeners.get(event)!
      for (const [listener, count] of eventListeners.entries()) {
        if (count > 0) {
          try {
            const result = listener(payload)
            results.push(result)
          } catch (e) {
            continue
          }
        }
      }
      return results
    },

    listenerCount(event: string): number {
      if (!listeners.has(event)) {
        return 0
      }
      let count = 0
      for (const [, c] of listeners.get(event)!.entries()) {
        count += c
      }
      return count
    }
  }
}

export { createEventEmitter }
```

