type RateLimitEntry = {
  startTime: number;
  count: number;
};

export function createRateLimiter(): () => {
  checkAndConsume(key: string, nowMs: number): boolean;
  reset(key: string): void;
} {
  const storage = new Map<string, RateLimitEntry>();
  const policy = { maxRequests: 3, windowDuration: 1000 };

  return {
    checkAndConsume(key: string, nowMs: number): boolean {
      let entry = storage.get(key);

      if (!entry) {
        entry = { startTime: nowMs, count: 0 };
        storage.set(key, entry);
      }

      const elapsed = nowMs - entry.startTime;

      if (elapsed >= policy.windowDuration) {
        entry.startTime = nowMs;
        entry.count = 0;
      }

      entry.count += 1;

      return entry.count <= policy.maxRequests;
    },

    reset(key: string): void {
      storage.set(key, undefined);
    },
  };
}
