export function createRateLimiter(): RateLimiter {
  const windows = new Map<string, { windowStart: number; count: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      const limit = 3
      const windowMs = 1000

      let entry = windows.get(key)

      if (!entry || (nowMs - entry.windowStart >= windowMs)) {
        // New key or expired window - start fresh with current request counted
        entry = { windowStart: nowMs, count: 1 }
        windows.set(key, entry)
        return true
      }

      if (entry.count < limit) {
        entry.count++
        windows.set(key, entry)
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      const limit = 3
      const windowMs = 1000

      const entry = windows.get(key)

      // No entry or expired → full quota available
      if (!entry || (nowMs - entry.windowStart >= windowMs)) {
        return limit
      }

      const elapsed = nowMs - entry.windowStart

      // Check boundary reset rule
      if (elapsed >= windowMs) {
        // Start fresh window
        return limit
      }

      // Still in current window, some quota may have been used
      return Math.max(0, limit - entry.count)
    },

    reset(key: string): void {
      windows.delete(key)
    }
  }
}
