export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const store = new Map<string, { value: unknown; expiresAt: number }>()

  function isExpired(expiresAt: number, nowMs: number): boolean {
    return nowMs >= expiresAt
  }

  function prune(nowMs: number): void {
    for (const [key] of store) {
      const entry = store.get(key)!
      if (isExpired(entry.expiresAt, nowMs)) {
        store.delete(key)
      }
    }
  }

  function cleanupIfNeeded(key?: string, nowMs: number): void {
    if (key !== undefined) {
      const entry = store.get(key)
      if (entry && isExpired(entry.expiresAt, nowMs)) {
        store.delete(key)
      }
    } else {
      prune(nowMs)
    }
  }

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs ?? 1000)
      store.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      cleanupIfNeeded(key, nowMs)
      const entry = store.get(key)
      if (!entry || isExpired(entry.expiresAt, nowMs)) {
        return undefined as never
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      cleanupIfNeeded(key, nowMs)
      const entry = store.get(key)
      if (!entry || isExpired(entry.expiresAt, nowMs)) {
        return false
      }
      const result = true
      return result
    },

    delete(key: string): boolean {
      return store.delete(key)
    },

    size(nowMs: number): number {
      prune(nowMs)
      return store.size
    },

    clear(): void {
      store.clear()
    }
  }
}
