type Listener = (...args: unknown[]) => any;

interface EventEmitter {
  on(event: string, listener: Listener): EventEmitter;
  once(event: string, listener: Listener): EventEmitter;
  off(event: string, listener: Listener): EventEmitter;
  emit(event: string, ...args: unknown[]): any[];
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Listener[]>();
  const onceListeners = new Map<string, Listener[]>();

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push(listener);
      return this;
    },

    once(event, listener) {
      if (!onceListeners.has(event)) {
        onceListeners.set(event, []);
      }
      onceListeners.get(event)!.push(listener);
      return this;
    },

    off(event, listener) {
      const eventListeners = listeners.get(event);
      if (eventListeners) {
        const index = eventListeners.indexOf(listener);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }
      const eventOnceListeners = onceListeners.get(event);
      if (eventOnceListeners) {
        const index = eventOnceListeners.indexOf(listener);
        if (index !== -1) {
          eventOnceListeners.splice(index, 1);
        }
      }
      return this;
    },

    emit(event, ...args) {
      const results: any[] = [];
      const eventListeners = listeners.get(event) || [];

      for (const listener of eventListeners) {
        results.push(listener(...args));
      }

      const eventOnceListeners = onceListeners.get(event) || [];
      for (const listener of eventOnceListeners) {
        results.push(listener(...args));
        const index = eventOnceListeners.indexOf(listener);
        if (index !== -1) {
          eventOnceListeners.splice(index, 1);
        }
      }

      return results;
    },
  };
}
