```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>()

  return {
    on(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const arr = listeners.get(event)!
      arr.push({ listener, once: false })
      return arr.length
    },

    once(event, listener) {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      const arr = listeners.get(event)!
      arr.push({ listener, once: true })
      return arr.length
    },

    off(event, listener) {
      const arr = listeners.get(event)
      if (!arr) return false

      const index = arr.findIndex(l => l.listener === listener)
      if (index === -1) return false

      arr.splice(index, 1)
      return true
    },

    emit(event, payload) {
      const arr = listeners.get(event)
      if (!arr) return []

      const results: unknown[] = []
      const toRemove: number[] = []

      for (let i = 0; i < arr.length; i++) {
        const { listener, once } = arr[i]
        results.push(listener(payload))
        if (once) {
          toRemove.push(i)
        }
      }

      for (let i = toRemove.length - 1; i >= 0; i--) {
        arr.splice(toRemove[i], 1)
      }

      return results
    },

    listenerCount(event) {
      const arr = listeners.get(event)
      return arr ? arr.length : 0
    }
  }
}
