export function createRateLimiter() {
  const WINDOW_SIZE_MS = 1000;
  const MAX_REQUESTS = 3;

  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const currentEntry = state.get(key);

      if (!currentEntry || (nowMs - currentEntry.windowStart) >= WINDOW_SIZE_MS) {
        state.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (currentEntry.count < MAX_REQUESTS) {
        currentEntry.count++;
        return true;
      }

      return false;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}
