interface RateLimiterState {
  count: number;
  windowStart: number;
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

const LIMIT = 3;
const WINDOW_MS = 1000;

export function createRateLimiter(): RateLimiter {
  const stateMap = new Map<string, RateLimiterState>();

  return {
    allow(key, nowMs) {
      let state = stateMap.get(key);

      if (!state || nowMs - state.windowStart >= WINDOW_MS) {
        state = { count: 0, windowStart: nowMs };
        stateMap.set(key, state);
      }

      if (state.count < LIMIT) {
        state.count++;
        return true;
      }

      return false;
    },

    remaining(key, nowMs) {
      const state = stateMap.get(key);

      if (!state || nowMs - state.windowStart >= WINDOW_MS) {
        return LIMIT;
      }

      const rem = LIMIT - state.count;
      return rem < 0 ? 0 : rem;
    },

    reset(key) {
      stateMap.delete(key);
    }
  };
}
