type Todo = {
  id: number;
  text: string;
  completed: boolean;
};

export function createTodoApp() {
  let todos: Map<number, Todo> = new Map();
  let nextId: number = 1;

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId++,
        text,
        completed: false,
      };
      todos.set(todo.id, todo);
      return todo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.get(id);
    },

    toggleTodo(id: number): void {
      const todo = todos.get(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      return todos.delete(id);
    },

    listTodos(): Array<Todo> {
      return Array.from(todos.values());
    },

    listCompleted(): Array<Todo> {
      return Array.from(todos.values()).filter((todo) => todo.completed);
    },

    listPending(): Array<Todo> {
      return Array.from(todos.values()).filter((todo) => !todo.completed);
    },

    clearCompleted(): void {
      const idsToRemove: number[] = [];
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) {
          idsToRemove.push(id);
        }
      }
      for (const id of idsToRemove) {
        todos.delete(id);
      }
    },
  };
}
