type Entry = {
  value: unknown
  expiresAt: number
}

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const storage = new Map<string, Entry>()

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const expiresAt = nowMs + (ttlMs !== undefined ? ttlMs : 1000)
      storage.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = storage.get(key)
      if (!entry || nowMs >= entry.expiresAt) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = storage.get(key)
      return entry !== undefined && nowMs < entry.expiresAt
    },

    delete(key: string): boolean {
      const entry = storage.get(key)
      if (!entry || entry.expiresAt <= 0) {
        return false
      }
      return storage.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of storage.values()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      storage.clear()
    }
  }
}
