```typescript
interface CacheEntry {
  value: unknown
  expiresAt: number
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

function isExpired(entry: CacheEntry | undefined, nowMs: number): boolean {
  return entry === undefined || nowMs >= entry.expiresAt
}

export function createTtlCache(): TtlCache {
  const cache = new Map<string, CacheEntry>()
  const DEFAULT_TTL_MS = 1000

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL_MS): void {
      const expiresAt = nowMs + ttlMs
      cache.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = cache.get(key)
      if (isExpired(entry, nowMs)) {
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = cache.get(key)
      return !isExpired(entry, nowMs)
    },

    delete(key: string): boolean {
      return cache.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of cache.values()) {
        if (!isExpired(entry, nowMs)) {
          count++
        }
      }
      return count
    },

    clear(): void {
      cache.clear()
    }
  }
}
