type Listener = (...args: any[]) => any;
interface ListenerMeta {
  once: boolean;
}

function createEventEmitter() {
  const events = new Map<string, Array<ListenerMeta & { handler: Listener }>>();

  function on(event: string, listener: Listener, options?: { once?: boolean }): void {
    if (!events.has(event)) {
      events.set(event, []);
    }
    events.get(event)!.push({ handler: listener, once: options?.once || false });
  }

  function once(event: string, listener: Listener): void {
    on(event, listener, { once: true });
  }

  function off(event: string, listener: Listener): void {
    const listeners = events.get(event);
    if (!listeners) return;
    const idx = listeners.findIndex(l => l.handler === listener);
    if (idx !== -1) {
      listeners.splice(idx, 1);
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const listeners = events.get(event);
    if (!listeners || listeners.length === 0) {
      return [];
    }

    const results: any[] = [];
    const toRemove: Listener[] = [];

    for (const meta of listeners) {
      try {
        const result = meta.handler(...args);
        results.push(result);
      } catch (_) {}
      if (meta.once) {
        toRemove.push(meta.handler);
      }
    }

    for (const handler of toRemove) {
      const idx = listeners.findIndex(l => l.handler === handler);
      if (idx !== -1) {
        listeners.splice(idx, 1);
      }
    }

    return results;
  }

  return { on, once, off, emit };
}

export { createEventEmitter };
