```typescript
type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Set<Listener>>()

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, new Set())
      }
      listeners.get(event)!.add(listener)
      return listeners.get(event)!.size
    },

    once(event: string, listener: Listener): number {
      const wrapper = (payload: unknown): unknown => {
        listener(payload)
        return off(event, wrapper)
      }
      if (!listeners.has(event)) {
        listeners.set(event, new Set())
      }
      listeners.get(event)!.add(wrapper)
      return listeners.get(event)!.size
    },

    off(event: string, listener: Listener): boolean {
      const eventListeners = listeners.get(event)
      if (!eventListeners) {
        return false
      }
      const removed = eventListeners.delete(listener)
      if (eventListeners.size === 0) {
        listeners.delete(event)
      }
      return removed
    },

    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = listeners.get(event)
      if (!eventListeners) {
        return []
      }
      const results: unknown[] = []
      for (const listener of eventListeners) {
        try {
          results.push(listener(payload))
        } catch (err) {
          // Silently continue on error as per spec
        }
      }
      return results
    },

    listenerCount(event: string): number {
      const eventListeners = listeners.get(event)
      return eventListeners ? eventListeners.size : 0
    }
  }
}
