type RateLimitWindow = {
  windowStart: number;
  count: number;
};

interface RateLimiter {
  tryAcquire(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

interface LimitsPolicy {
  maxRequests: number;
  windowMs: number;
}

function createRateLimiter(
  policy: Partial<LimitsPolicy> = {}
): RateLimiter {
  const maxRequests = policy.maxRequests ?? 3;
  const windowMs = policy.windowMs ?? 1000;
  const windows = new Map<string, RateLimitWindow>();

  function tryAcquire(key: string, nowMs: number): boolean {
    const existing = windows.get(key);
    const windowEnd = (existing?.windowStart ?? -Infinity) + windowMs;

    if (nowMs >= windowEnd || !existing) {
      windows.set(key, { windowStart: nowMs, count: 1 });
      return true;
    }

    if (existing.count < maxRequests) {
      existing.count++;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    windows.delete(key);
  }

  return { tryAcquire, reset };
}

export { createRateLimiter };
