export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<string, { startMs: number; count: number }>()

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key)

      if (!entry) {
        state.set(key, { startMs: nowMs, count: 1 })
        return true
      }

      if (nowMs - entry.startMs >= windowMs) {
        entry.startMs = nowMs
        entry.count = 1
        return true
      }

      if (entry.count < limit) {
        entry.count++
        return true
      }

      return false
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key)

      if (!entry) {
        return limit
      }

      if (nowMs - entry.startMs >= windowMs) {
        return limit
      }

      return Math.max(0, limit - entry.count)
    },

    reset(key: string): void {
      state.delete(key)
    },
  }
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
