  listCompleted(): Array<{ id: number; text: string; completed: boolean }>;
  listPending(): Array<{ id: number; text: string; completed: boolean }>;
  clearCompleted(): void;
}

export function createTodoApp(): CreateTodoAppReturn {
  const todos = new Map<number, Todo>();
  let nextId = 1 as number;

  return {
    addTodo(text) {
      const id = nextId++;
      const todo: Todo = { id, text, completed: false };
      todos.set(id, todo);
      return todo;
    },

    getTodo(id) {
      return todos.get(id);
    },

    toggleTodo(id) {
      if (todos.has(id)) {
        const todo = todos.get(id)!;
        todo.completed = !todo.completed;
        todos.set(id, todo);
      }
    },

    deleteTodo(id) {
      return todos.delete(id);
    },

    listTodos() {
      return Array.from(todos.values());
    },

    listCompleted() {
      return todos.entries().reduce((acc, [id, todo]) => {
        if (todo.completed) acc.push({ ...todo });
        return acc;
      }, [] as Array<{ id: number; text: string; completed: boolean }>);
    },

    listPending() {
      return todos.entries().reduce((acc, [id, todo]) => {
        if (!todo.completed) acc.push({ ...todo });
        return acc;
      }, [] as Array<{ id: number; text: string; completed: boolean }>);
    },

    clearCompleted() {
      const idsToRemove = [];
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) idsToRemove.push(id);
      }
      for (const id of idsToRemove) {
        todos.delete(id);
      }
    },
  };
}
