```ts
interface TtlCacheEntry {
  value: unknown
  expiresAt: number
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

export function createTtlCache(): TtlCache {
  const entries = new Map<string, TtlCacheEntry>()
  const DEFAULT_TTL_MS = 1000

  return {
    set(key, value, nowMs, ttlMs = DEFAULT_TTL_MS) {
      if (ttlMs === 0) {
        // Immediate expiration means remove the entry
        entries.delete(key)
        return
      }
      const expiresAt = nowMs + ttlMs
      entries.set(key, { value, expiresAt })
    },

    get(key, nowMs): unknown {
      const entry = entries.get(key)
      if (entry) {
        if (nowMs >= entry.expiresAt) {
          entries.delete(key)
          return undefined
        }
        return entry.value
      }
      return undefined
    },

    has(key, nowMs): boolean {
      const entry = entries.get(key)
      if (!entry) {
        return false
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return false
      }
      return true
    },

    delete(key): boolean {
      return entries.delete(key)
    },

    size(nowMs): number {
      let count = 0
      for (const [key, entry] of entries) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    }
  }
}
